def _lazy_analytics_export(rows_by_table: dict[str, list[dict[str, Any]]]) -> dict[str, Any]:
    live_bigquery = any(
        os.getenv(name, "").strip().lower() in {"1", "true", "yes", "on"}
        for name in ("PARKPULSE_LIVE_BIGQUERY", "PARKPULSE_COLLABORATION_LIVE_BIGQUERY")
    )
    if live_bigquery:
        from bigquery_analytics import export_analytics_rows

        return export_analytics_rows(rows_by_table)
    return {
        "status": "disabled",
        "mode": "analytics_export_disabled",
        "row_counts": {table: len(rows) for table, rows in rows_by_table.items()},
        "readiness_issues": ["PARKPULSE_LIVE_BIGQUERY is not enabled for lazy sweep routes."],
    }


async def _export_live_episode_fitness_to_bigquery(limit: int = 80) -> dict[str, Any]:
    if _fast_park_simulation is None or not hasattr(_fast_park_simulation, "get_episode_fitness"):
        return {"status": "unavailable", "mode": "live_episode_fitness_export", "row_counts": {}}
    payload = await _fast_park_simulation.get_episode_fitness(limit=limit)
    episodes = payload.get("episodes", []) if isinstance(payload.get("episodes"), list) else []
    rows_by_table: dict[str, list[dict[str, Any]]] = {"outcome_events": [], "action_dispatches": [], "eval_results": []}
    exported_ids: list[str] = []
    try:
        from bigquery_analytics import build_analytics_rows, export_analytics_rows
    except Exception as error:
        return {"status": "error", "mode": "live_episode_fitness_export", "row_counts": {}, "readiness_issues": [str(error)[:300]]}

    for episode in reversed(episodes):
        if not isinstance(episode, dict):
            continue
        episode_id = str(episode.get("id") or "")
        if not episode_id or episode_id in _exported_episode_fitness_ids:
            continue
        scores = episode.get("scores", {}) if isinstance(episode.get("scores"), dict) else {}
        pressure = episode.get("pressure", {}) if isinstance(episode.get("pressure"), dict) else {}
        difficulty = episode.get("difficulty", {}) if isinstance(episode.get("difficulty"), dict) else {}
        incidents = episode.get("active_random_incidents", []) if isinstance(episode.get("active_random_incidents"), list) else []
        action = episode.get("action", {}) if isinstance(episode.get("action"), dict) else {}
        fitness = float(scores.get("fitness") or 0)
        difficulty_adjusted = float(scores.get("difficulty_adjusted_fitness") or fitness)
        reward_delta = float(scores.get("reward_delta") or 0)
        pressure_reduction = float(pressure.get("reduction_vs_baseline") or 0)
        scenario_key = str(episode.get("scenario_key") or "live_complex_park")
        decision_id = f"{episode_id}_decision"
        outcome_id = f"{episode_id}_outcome"
        take_rate = max(0.0, min(0.99, 0.45 + reward_delta / 100))
        follow_rate = max(0.0, min(0.99, 0.5 + pressure_reduction / 100))
        positive_rate = max(0.0, min(0.99, fitness / 100))
        analytics_rows = build_analytics_rows(
            decision_id=decision_id,
            outcome_id=outcome_id,
            scenario_key=scenario_key,
            delivery={
                "response": {
                    "takeRate": take_rate,
                    "positiveResponseRate": positive_rate,
                    "reactiveFollowThroughRate": follow_rate,
                    "score": fitness,
                },
                "dispatches": [
                    {
                        "id": f"{episode_id}_action",
                        "channel": "runtime_action",
                        "targetSystem": str(action.get("target") or "park_runtime"),
                        "status": "observed",
                        "response": {
                            "takeRate": take_rate,
                            "positiveResponseRate": positive_rate,
                            "reactiveFollowThroughRate": follow_rate,
                        },
                    }
                ],
            },
            outcome={
                "learning": {
                    "take_rate_signal": (
                        f"Live complex park episode: action {action.get('target')}/{action.get('action')} scored "
                        f"{fitness:g}, reward delta {reward_delta:+g}, difficulty {difficulty.get('score', 0)}."
                    )
                },
                "state_impact": {
                    "headline": (
                        f"Live episode against {len(incidents)} random incident(s); pressure reduction "
                        f"{pressure_reduction:+g} vs no-action counterfactual."
                    )
                },
            },
            eval_result={
                "overall": difficulty_adjusted,
                "scorecard": {
                    "overall": difficulty_adjusted,
                    "response_score": fitness,
                    "status": "passed" if reward_delta > 0 else "review",
                    "policy_gate_status": "runtime_observed",
                },
                "dimension_scores": {
                    "fitness": fitness,
                    "reward_delta": reward_delta,
                    "pressure_reduction": pressure_reduction,
                    "difficulty": float(difficulty.get("score") or 0),
                    "incident_count": float(difficulty.get("active_random_incident_count") or len(incidents)),
                },
            },
            source="live_complex_park_episode",
        )
        for table, rows in analytics_rows.items():
            rows_by_table.setdefault(table, []).extend(rows)
        exported_ids.append(episode_id)

    if not exported_ids:
        return {
            "status": "no_new_rows",
            "mode": "live_episode_fitness_export",
            "row_counts": {table: len(rows) for table, rows in rows_by_table.items()},
            "episode_count": len(episodes),
        }
    export = export_analytics_rows(rows_by_table)
    if export.get("status") == "exported":
        _exported_episode_fitness_ids.update(exported_ids)
    export["mode"] = "live_episode_fitness_export"
    export["episode_ids"] = exported_ids
    return export


async def _send_json(send, status: int, payload: dict[str, Any]) -> None:
    body = json.dumps(payload, default=str).encode("utf-8")
    await send(
        {
            "type": "http.response.start",
            "status": status,
            "headers": [
                (b"content-type", b"application/json"),
                (b"content-length", str(len(body)).encode("ascii")),
                (b"cache-control", b"no-store"),
                (b"access-control-allow-origin", b"*"),
                (b"access-control-allow-methods", b"GET,POST,PUT,OPTIONS"),
                (b"access-control-allow-headers", b"authorization,content-type,x-parkpulse-role,x-parkpulse-role-token"),
            ],
        }
    )
    await send({"type": "http.response.body", "body": body})


def _scope_header(scope: dict[str, Any], name: str) -> str:
    target = name.lower().encode("latin-1")
    for key, value in scope.get("headers", []) or []:
        if key == target:
            return value.decode("latin-1") if isinstance(value, bytes) else str(value)
    return ""


def _cors_origin_for_scope(scope: dict[str, Any]) -> bytes:
    origin = _scope_header(scope, "origin").strip()
    if not origin:
        return b"*"
    allowed = [
        item.strip()
        for item in os.getenv("PARKPULSE_ALLOWED_ORIGINS", "").split(",")
        if item.strip()
    ]
    if (
        origin in allowed
        or origin.startswith("http://127.0.0.1:")
        or origin.startswith("http://localhost:")
        or origin.startswith("http://0.0.0.0:")
    ):
        return origin.encode("latin-1")
    return b"*"


def _cors_preflight_headers(scope: dict[str, Any]) -> list[tuple[bytes, bytes]]:
    requested_headers = _scope_header(scope, "access-control-request-headers").strip()
    return [
        (b"access-control-allow-origin", _cors_origin_for_scope(scope)),
        (b"access-control-allow-methods", b"GET,POST,PUT,OPTIONS"),
        (
            b"access-control-allow-headers",
            requested_headers.encode("latin-1")
            if requested_headers
            else b"authorization,content-type,x-parkpulse-role,x-parkpulse-role-token",
        ),
        (b"access-control-allow-credentials", b"true"),
        (b"access-control-max-age", b"600"),
        (b"content-length", b"0"),
    ]


async def _read_json_body(receive) -> dict[str, Any]:
    body = b""
    while True:
        event = await receive()
        if event.get("type") != "http.request":
            break
        body += event.get("body", b"")
        if not event.get("more_body"):
            break
    try:
        payload = json.loads(body.decode("utf-8") or "{}")
    except json.JSONDecodeError:
        return {}
    return payload if isinstance(payload, dict) else {}


def _request_headers(scope: dict[str, Any]) -> dict[str, str]:
    headers: dict[str, str] = {}
    for key, value in scope.get("headers") or []:
        try:
            header = key.decode("latin-1").lower() if isinstance(key, bytes) else str(key).lower()
            headers[header] = value.decode("latin-1") if isinstance(value, bytes) else str(value)
        except Exception:
            continue
    return headers


def _truthy(value: str | None, default: bool = False) -> bool:
    if value is None:
        return default
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def _role_auth_secret() -> str:
    return (os.getenv("PARKPULSE_ROLE_AUTH_SECRET") or "parkpulse-local-dev-secret-change-before-production").strip()


def _signed_role_required() -> bool:
    return _truthy(os.getenv("PARKPULSE_REQUIRE_SIGNED_ROLE_TOKEN"), False) or _truthy(os.getenv("PARKPULSE_REQUIRE_SIGNED_ROLE_FOR_MUTATION"), False)


def _dev_role_issuer_enabled() -> bool:
    configured = os.getenv("PARKPULSE_ENABLE_DEV_ROLE_ISSUER")
    if configured is not None:
        return _truthy(configured, True)
    return False


def _role_session_ttl_seconds() -> int:
    return max(300, _int_env("PARKPULSE_ROLE_SESSION_TTL_SECONDS", 3600))


def _role_session_issuer_key() -> str:
    return os.getenv("PARKPULSE_ROLE_SESSION_ISSUER_KEY") or ""


def _trusted_role_issuer_enabled() -> bool:
    return bool(_role_session_issuer_key().strip())


def _issuer_key_from_scope(scope: dict[str, Any]) -> str:
    return str(_request_headers(scope).get("x-parkpulse-role-issuer-key") or "")


def _issuer_key_matches(candidate: str) -> bool:
    import hmac

    expected = _role_session_issuer_key().strip()
    supplied = str(candidate or "").strip()
    return bool(expected and supplied and hmac.compare_digest(expected, supplied))


def _extract_role_token(headers: dict[str, str]) -> str | None:
    explicit_role_token = headers.get("x-parkpulse-role-token")
    if explicit_role_token:
        return explicit_role_token
    authorization = headers.get("authorization") or ""
    if authorization.lower().startswith("bearer "):
        return authorization.split(" ", 1)[1].strip()
    return None


def _request_role_context(scope: dict[str, Any], payload: dict[str, Any] | None = None, default: str = "ops_team") -> dict[str, Any]:
    headers = _request_headers(scope)
    external_identity = verify_external_role_identity(headers, default_role=default)
    if external_identity.get("authenticated") or external_identity.get("status") == "role_unmapped":
        return external_identity
    token_status = verify_role_session(_extract_role_token(headers), _role_auth_secret())
    if token_status.get("authenticated"):
        return {
            "status": "authenticated",
            "authenticated": True,
            "auth_method": "signed_role_session",
            "role": token_status.get("role"),
            "subject": token_status.get("subject"),
            "issuer": token_status.get("issuer"),
            "expires_at": token_status.get("expires_at"),
            "token_status": token_status.get("status"),
        }
    role = headers.get("x-parkpulse-role") or headers.get("x-role")
    if not role and isinstance(payload, dict):
        role = payload.get("role") or payload.get("actor_role") or payload.get("actorRole")
    if _signed_role_required():
        return {
            "status": "unauthenticated",
            "authenticated": False,
            "auth_method": "signed_role_session_required",
            "role": normalize_role(str(role) if role is not None else None, default=default),
            "subject": "",
            "token_status": token_status.get("status"),
            "reason": "Signed ParkPulse role session is required for this mutation.",
        }
    return {
        "status": "authenticated",
        "authenticated": True,
        "auth_method": "unsigned_dev_role_header",
        "role": normalize_role(str(role) if role is not None else None, default=default),
        "subject": "unsigned-local-dev",
        "token_status": token_status.get("status"),
    }


def _authorization_response(decision: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": "blocked",
        "mode": "role_authorization_gate",
        "authorization": decision,
        "readiness_issues": [decision.get("reason") or "Role is not authorized for this capability."],
        "boundary": "Role authorization is enforced before protected ParkPulse reads/actions. Signed local role sessions are used here; production should replace the local issuer with a real identity provider.",
        "uses_seed_data": False,
        "loads_bigquery_per_tick": False,
        "llm_control_authority": False,
    }


def _record_role_authorization(scope: dict[str, Any], decision: dict[str, Any]) -> None:
    event = {
        "id": f"role-auth-{int(time.time() * 1000)}-{hashlib.sha1(json.dumps(decision, sort_keys=True, default=str).encode('utf-8')).hexdigest()[:8]}",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "method": scope.get("method"),
        "path": scope.get("path"),
        **decision,
    }
    _write_jsonl_event(_role_authorization_log_path(), event)

    def persist_durable_audit() -> None:
        try:
            from park_role_access_audit import record_role_access_audit_event
        except Exception:
            return
        identity = decision.get("identity") if isinstance(decision.get("identity"), dict) else {}
        try:
            record_role_access_audit_event(
                "mutation_allowed" if decision.get("allowed") else "mutation_denied",
                role=decision.get("role"),
                subject=identity.get("subject"),
                capability=decision.get("capability"),
                resource=decision.get("resource"),
                status=decision.get("status"),
                reason=decision.get("reason"),
            )
        except Exception:
            pass

    if _truthy(os.getenv("PARKPULSE_ROLE_AUTH_DURABLE_AUDIT_INLINE"), False):
        persist_durable_audit()
        return
    try:
        _role_auth_audit_executor.submit(persist_durable_audit)
    except Exception:
        pass


async def _authorize_or_send(
    send,
    scope: dict[str, Any],
    capability: str,
    resource: str,
    payload: dict[str, Any] | None = None,
    detail: str | None = None,
    default_role: str = "ops_team",
) -> dict[str, Any] | None:
    identity = _request_role_context(scope, payload, default=default_role)
    decision = authorize_role_action(identity.get("role"), capability, resource=resource, detail=detail, default_role=default_role)
    decision["identity"] = identity
    if not identity.get("authenticated"):
        decision["status"] = "unauthenticated"
        decision["allowed"] = False
        decision["reason"] = identity.get("reason") or "Signed role session token is required."
    _record_role_authorization(scope, decision)
    if decision.get("allowed"):
        return decision
    await _send_json(send, 401 if decision.get("status") == "unauthenticated" else 403, _authorization_response(decision))
    return None


def _role_authorization_payload(payload: dict[str, Any], scope: dict[str, Any] | None = None) -> dict[str, Any]:
    capability = str(payload.get("capability") or "").strip()
    if not capability:
        return {"status": "error", "mode": "role_authorization_check", "readiness_issues": ["capability is required."]}
    identity = _request_role_context(scope or {}, payload, default="ops_team") if scope is not None else {}
    role = payload.get("role") or payload.get("actor_role") or payload.get("actorRole") or identity.get("role")
    decision = authorize_role_action(
        str(role or "ops_team"),
        capability,
        resource=str(payload.get("resource") or ""),
        detail=str(payload.get("detail") or ""),
        default_role="ops_team",
    )
    if identity:
        decision["identity"] = identity
    return {
        "status": decision.get("status"),
        "mode": "role_authorization_check",
        "authorization": decision,
        "uses_seed_data": False,
        "loads_bigquery_per_tick": False,
        "llm_control_authority": False,
    }


def _experience_studio_role_gate_enabled() -> bool:
    return str(os.getenv("PARKPULSE_ENFORCE_EXPERIENCE_STUDIO_ROLES", "")).strip().lower() in {"1", "true", "yes", "on"}


async def _authorize_experience_studio_or_send(
    send,
    scope: dict[str, Any],
    capability: str,
    resource: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not _experience_studio_role_gate_enabled():
        return {
            "status": "disabled",
            "allowed": True,
            "capability": capability,
            "resource": resource,
            "reason": "Experience Studio role gate is disabled for local/demo mode.",
        }
    return await _authorize_or_send(send, scope, capability, resource, payload, default_role="ops_team")


def _durable_role_authorization_rows(limit: int) -> list[dict[str, Any]]:
    try:
        from park_role_access_audit import role_access_audit_status

        payload = role_access_audit_status(limit=limit)
    except Exception:
        return []
    events = payload.get("events", []) if isinstance(payload.get("events"), list) else []
    rows: list[dict[str, Any]] = []
    for event in events:
        if not isinstance(event, dict):
            continue
        event_type = str(event.get("event_type") or "")
        allowed = False if event_type in {"mutation_denied", "role_session_denied"} else True if event_type in {"mutation_allowed", "role_session_issued"} else None
        rows.append(
            {
                "id": event.get("_id") or event.get("id"),
                "created_at": event.get("createdAt") or event.get("created_at"),
                "method": None,
                "path": "/api/park/operator-command" if event_type == "mutation_denied" and event.get("resource") == "operator_command" else None,
                "role": event.get("role"),
                "capability": event.get("capability"),
                "resource": event.get("resource"),
                "status": event.get("status"),
                "reason": event.get("reason"),
                "allowed": allowed,
                "identity": {"subject": event.get("subject")} if event.get("subject") else {},
                "audit_storage": payload.get("storage"),
                "audit_event_type": event_type,
            }
        )
    return rows


def _identity_readiness_payload() -> dict[str, Any]:
    secret = _role_auth_secret()
    default_secret = secret == "parkpulse-local-dev-secret-change-before-production"
    provider_readiness = identity_provider_readiness()
    external_ready = bool(provider_readiness.get("external_identity_ready"))
    return {
        "status": "production_ready" if external_ready and not default_secret else "dev_signed_sessions",
        "mode": "identity_readiness",
        "signed_role_required": _signed_role_required(),
        "dev_role_issuer_enabled": _dev_role_issuer_enabled(),
        "token_ttl_seconds": _role_session_ttl_seconds(),
        **provider_readiness,
        "production_ready": external_ready and not default_secret,
        "remaining_gap": None
        if external_ready and not default_secret
        else "Replace the local dev issuer with Google IAP/OIDC/Firebase and set PARKPULSE_ROLE_AUTH_SECRET before production.",
        "uses_seed_data": False,
        "loads_bigquery_per_tick": False,
        "llm_control_authority": False,
    }


