def _monitor_evidence_terms(*values: Any) -> set[str]:
    blob = " ".join(str(value or "") for value in values)
    return {
        term
        for term in re.split(r"[^a-z0-9]+", blob.lower())
        if len(term) >= 4 and term not in _MONITOR_EVIDENCE_STOPWORDS
    }


def _monitor_shared_term_count(terms: set[str], *values: Any) -> int:
    if not terms:
        return 0
    haystack = _monitor_evidence_terms(*values)
    return sum(1 for term in terms if term in haystack)


def _monitor_case_hard_terms(case_row: dict[str, Any]) -> set[str]:
    case_id_terms = _monitor_evidence_terms(case_row.get("id"))
    title_terms = _monitor_evidence_terms(case_row.get("title"))
    domain_terms = _monitor_evidence_terms(case_row.get("domain"), case_row.get("severity"))
    hard = case_id_terms | {term for term in title_terms if term not in domain_terms}
    return {term for term in hard if term not in {"high", "warning", "critical"}}


def _monitor_list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _monitor_dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _monitor_unique(values: list[Any], limit: int = 12) -> list[str]:
    seen: set[str] = set()
    rows: list[str] = []
    for value in values:
        text = str(value or "").strip()
        if text and text not in seen:
            seen.add(text)
            rows.append(text)
        if len(rows) >= limit:
            break
    return rows


def _monitor_trace_url(trace_id: Any) -> str | None:
    trace_text = str(trace_id or "").strip()
    if not trace_text:
        return None
    project = os.getenv("GOOGLE_CLOUD_PROJECT") or os.getenv("GCP_PROJECT") or os.getenv("PROJECT_ID")
    span_id = ""
    for template_name in ("ARIZE_TRACE_URL_TEMPLATE", "GCP_TRACE_URL_TEMPLATE"):
        template = os.getenv(template_name)
        if template:
            try:
                return template.format(trace_id=trace_text, span_id=span_id, project=project or "")
            except Exception:
                continue
    if project:
        return f"https://console.cloud.google.com/traces/list?project={project}&tid={trace_text}"
    return None


def _monitor_file_signature(path: Path) -> dict[str, Any]:
    try:
        stat = path.stat()
    except OSError:
        return {"path": str(path), "exists": False, "size": 0, "mtime_ns": 0}
    return {"path": str(path), "exists": True, "size": stat.st_size, "mtime_ns": stat.st_mtime_ns}


def _monitor_policy_source_paths() -> list[Path]:
    base_dir = Path(__file__).resolve().parent
    paths = [base_dir / "policy_book.json"]
    policy_dir = base_dir / "policy_books"
    if policy_dir.exists():
        paths.extend(sorted(policy_dir.glob("*.json")))
    return paths


def _monitor_source_watermark() -> dict[str, Any]:
    runtime_dir = Path(os.getenv("PARKPULSE_RUNTIME_DIR", "/tmp/parkpulse"))
    source_paths = [
        Path(os.getenv("PARKPULSE_AGENT_OPS_LEDGER") or runtime_dir / "agent_ops_ledger.jsonl"),
        Path(os.getenv("PARKPULSE_REVIEW_LEDGER_LOG_PATH") or runtime_dir / "review_ledger.jsonl"),
        Path(os.getenv("PARKPULSE_LIVE_FEED_EVENT_LOG_PATH") or runtime_dir / "live_feed_events.jsonl"),
        *_monitor_policy_source_paths(),
    ]
    files = [_monitor_file_signature(path) for path in source_paths]
    fingerprint = hashlib.sha1(json.dumps(files, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")).hexdigest()
    return {
        "fingerprint": fingerprint,
        "files": files,
        "policy_file_count": sum(1 for item in files if str(item.get("path", "")).endswith(".json") and item.get("exists")),
        "ledger_file_count": sum(1 for item in files if str(item.get("path", "")).endswith(".jsonl") and item.get("exists")),
    }


def _monitor_policy_case_for(case_row: dict[str, Any], policy_cases: list[dict[str, Any]], terms: set[str]) -> dict[str, Any]:
    case_id = str(case_row.get("id") or "")
    exact = next((item for item in policy_cases if isinstance(item, dict) and str(item.get("id") or "") == case_id), None)
    if isinstance(exact, dict):
        return exact
    scored = [
        (
            _monitor_shared_term_count(
                terms,
                item.get("id"),
                item.get("title"),
                " ".join(map(str, _monitor_list(item.get("triggers")))),
                " ".join(map(str, _monitor_list(item.get("state_signals")))),
            ),
            item,
        )
        for item in policy_cases
        if isinstance(item, dict)
    ]
    scored = [row for row in scored if row[0] > 0]
    return sorted(scored, key=lambda row: row[0], reverse=True)[0][1] if scored else {}


def _policy_ref_detail(policy_ref: str) -> dict[str, Any]:
    if _fast_get_policy_books is None:
        return {"status": "unavailable", "policy_ref": policy_ref, "readiness_issues": ["Policy book loader is unavailable."]}
    books = _fast_get_policy_books()
    matches: list[dict[str, Any]] = []
    related_cases: list[dict[str, Any]] = []
    for envelope in _monitor_list(books.get("policy_books")):
        if not isinstance(envelope, dict):
            continue
        content = _monitor_dict(envelope.get("content"))
        book_id = str(content.get("policy_book_id") or envelope.get("source") or "")
        for rule in _monitor_list(content.get("decision_rules")):
            if isinstance(rule, dict) and str(rule.get("id") or "") == policy_ref:
                matches.append(
                    {
                        "kind": "decision_rule",
                        "policy_ref": policy_ref,
                        "policy_book_id": book_id,
                        "title": rule.get("name") or policy_ref,
                        "condition": rule.get("condition"),
                        "allowed_action": rule.get("allowed_action"),
                        "blocked_action": rule.get("blocked_action"),
                        "required_evidence": _monitor_list(rule.get("required_evidence")),
                        "human_review_if": _monitor_list(rule.get("human_review_if")),
                        "applies_to": _monitor_dict(rule.get("applies_to")),
                        "block_conditions": _monitor_list(rule.get("block_conditions")),
                        "review_conditions": _monitor_list(rule.get("review_conditions")),
                        "raw": rule,
                    }
                )
        judges = content.get("judges", {}) if isinstance(content.get("judges"), dict) else {}
        for judge_id, judge in judges.items():
            if isinstance(judge, dict) and str(judge.get("policy_ref") or "") == policy_ref:
                matches.append(
                    {
                        "kind": "judge",
                        "policy_ref": policy_ref,
                        "policy_book_id": book_id,
                        "title": judge.get("name") or judge_id,
                        "summary": judge.get("description") or judge.get("purpose"),
                        "raw": judge,
                    }
                )
        for action_case in _monitor_list(content.get("action_cases")):
            if isinstance(action_case, dict) and policy_ref in {str(item) for item in _monitor_list(action_case.get("policy_refs"))}:
                related_cases.append(
                    {
                        "id": action_case.get("id"),
                        "title": action_case.get("title"),
                        "triggers": _monitor_list(action_case.get("triggers")),
                        "blocked_actions": _monitor_list(action_case.get("blocked_actions")),
                        "success_metric": action_case.get("success_metric"),
                        "rollback_condition": action_case.get("rollback_condition"),
                    }
                )
    return {
        "status": "found" if matches or related_cases else "not_found",
        "mode": "policy_ref_detail",
        "policy_ref": policy_ref,
        "match_count": len(matches),
        "matches": matches,
        "related_cases": related_cases[:20],
    }


def _monitor_receipt_relation(case_row: dict[str, Any], receipt: dict[str, Any], terms: set[str], hard_terms: set[str]) -> dict[str, Any]:
    case_id = str(case_row.get("id") or "")
    receipt_case_id = str(receipt.get("caseId") or receipt.get("case_id") or "")
    link_source = str(receipt.get("caseLinkSource") or receipt.get("case_link_source") or "")
    explicit = bool(case_id and receipt_case_id == case_id and link_source != "doctrine_inferred")
    relation_text = (
        receipt.get("summary"),
        receipt.get("scenarioName"),
        receipt.get("selectedAction"),
        " ".join(map(str, _monitor_list(receipt.get("receiverActions")))),
        " ".join(map(str, _monitor_list(receipt.get("retrievalTags")))),
        " ".join(map(str, _monitor_list(receipt.get("failureReasons")))),
    )
    score = 100 if explicit else _monitor_shared_term_count(terms, *relation_text)
    hard_match = bool(hard_terms and _monitor_shared_term_count(hard_terms, *relation_text))
    include = explicit or (hard_match and score >= 1) or score >= 3
    confidence = "direct" if explicit else "inferred_high" if hard_match and score >= 2 else "inferred" if include else "weak"
    return {"score": score, "type": "explicit_case_id" if explicit else "semantic_terms", "hard_match": hard_match, "include": include, "confidence": confidence}


def _monitor_review_relation(case_row: dict[str, Any], review: dict[str, Any], terms: set[str], hard_terms: set[str]) -> dict[str, Any]:
    case_id = str(case_row.get("id") or "")
    review_case_id = str(review.get("case_id") or review.get("caseId") or "")
    explicit = bool(case_id and review_case_id == case_id)
    event = _monitor_dict(review.get("event"))
    relation_text = (
        review.get("id"),
        review.get("reason"),
        review.get("owner"),
        review.get("priority"),
        event.get("source"),
        event.get("signal_type"),
        json.dumps(event.get("value"), default=str) if event.get("value") is not None else "",
    )
    score = 100 if explicit else _monitor_shared_term_count(terms, *relation_text)
    hard_match = bool(hard_terms and _monitor_shared_term_count(hard_terms, *relation_text))
    include = explicit or (hard_match and score >= 1) or score >= 3
    confidence = "direct" if explicit else "inferred_high" if hard_match and score >= 2 else "inferred" if include else "weak"
    return {"score": score, "type": "explicit_case_id" if explicit else "semantic_terms", "hard_match": hard_match, "include": include, "confidence": confidence}


def _monitor_eval_dimensions(case_row: dict[str, Any], receipts: list[dict[str, Any]], reviews: list[dict[str, Any]], policy_case: dict[str, Any]) -> list[dict[str, Any]]:
    quality = _monitor_dict(case_row.get("quality"))
    governance = _monitor_dict(case_row.get("governance"))
    evidence = _monitor_dict(case_row.get("productionEvidence"))
    base_score = _safe_float(quality.get("score"), 0.78)
    base_pct = round(base_score * 100) if 0 <= base_score <= 1 else round(base_score)
    latest_receipt = receipts[0] if receipts else {}
    latest_dims = _monitor_list(latest_receipt.get("evalDimensions"))
    if latest_dims:
        normalized: list[dict[str, Any]] = []
        for item in latest_dims[:6]:
            if not isinstance(item, dict):
                continue
            raw_score = item.get("score") if item.get("score") is not None else item.get("value")
            normalized.append(
                {
                    "id": str(item.get("id") or item.get("label") or "eval_dimension").lower().replace(" ", "_"),
                    "label": item.get("label") or item.get("id") or "Eval dimension",
                    "score": _safe_float(raw_score, base_pct),
                    "status": item.get("status") or "measured",
                    "detail": item.get("detail") or item.get("why") or "Attached from agent eval receipt.",
                }
            )
        if normalized:
            return normalized
    policy_score = 90 if policy_case else 58
    if _monitor_list(governance.get("blockerClasses")):
        policy_score = 62
    trace_score = min(96, 45 + len(receipts) * 15 + sum(1 for item in receipts if item.get("traceId")) * 10)
    review_score = 72 if reviews else 88
    if str(case_row.get("severity") or "").lower() in {"critical", "high"} and not reviews:
        review_score = 68
    freshness_score = min(94, 55 + int(_safe_float(evidence.get("feedCount"), 0)) * 8)
    return [
        {"id": "safety_policy", "label": "Safety and policy", "score": policy_score, "status": "linked" if policy_case else "missing_ref", "detail": "Policy doctrine is linked to this case." if policy_case else "No doctrine case matched this case."},
        {"id": "actionability", "label": "Actionability", "score": base_pct, "status": quality.get("status") or "measured", "detail": "Case quality score from the operating case index."},
        {"id": "trace_completeness", "label": "Trace completeness", "score": trace_score, "status": "linked" if receipts else "missing_trace", "detail": f"{len(receipts)} related receipts and tool traces."},
        {"id": "human_review_need", "label": "Human review need", "score": review_score, "status": "review_open" if reviews else "no_session", "detail": f"{len(reviews)} related human review sessions."},
        {"id": "evidence_freshness", "label": "Evidence freshness", "score": freshness_score, "status": evidence.get("state") or "demo_evidence", "detail": f"{evidence.get('feedCount') or 0} feeds attached to the case packet."},
    ]


async def _monitor_evidence_graph(case_id: str | None = None, *, limit: int = 30) -> dict[str, Any]:
    index = await _fast_case_index()
    case_rows = [row for row in _monitor_list(index.get("rows")) if isinstance(row, dict)]
    if case_id:
        case_rows = [row for row in case_rows if str(row.get("id") or "") == case_id] or case_rows[:1]
    policy = _fast_operational_doctrine_index() if _fast_operational_doctrine_index is not None else {}
    policy_cases = [row for row in _monitor_list(policy.get("action_cases")) if isinstance(row, dict)]
    policy_refs = [
        row if isinstance(row, dict) else {"policy_ref": str(row)}
        for row in _monitor_list(policy.get("policy_refs"))
        if isinstance(row, dict) or str(row or "").strip()
    ]
    try:
        from agent_ops_ledger import read_agent_ops_ledger

        ledger = await asyncio.wait_for(
            asyncio.to_thread(read_agent_ops_ledger, limit=max(1, min(limit, 80))),
            timeout=max(0.5, _float_env("PARKPULSE_AGENT_OPS_LEDGER_READ_TIMEOUT_SECONDS", 2.0)),
        )
    except Exception as error:
        ledger = {"status": "unavailable", "items": [], "readiness_issues": [str(error)[:240]]}
    try:
        reviews = review_training_ledger(limit=max(1, min(limit * 2, 160)))
    except Exception as error:
        reviews = {"status": "unavailable", "rows": [], "open_reviews": [], "readiness_issues": [str(error)[:240]]}
    receipts = [row for row in _monitor_list(ledger.get("items")) if isinstance(row, dict)]
    review_rows = [
        row
        for row in [*_monitor_list(reviews.get("open_reviews")), *_monitor_list(reviews.get("rows"))]
        if isinstance(row, dict)
    ]
    graph_cases: list[dict[str, Any]] = []
    policy_detail_cache: dict[str, dict[str, Any]] = {}

    def cached_policy_detail(ref_id: str) -> dict[str, Any]:
        if ref_id not in policy_detail_cache:
            policy_detail_cache[ref_id] = _policy_ref_detail(ref_id)
        return policy_detail_cache[ref_id]

    for row in case_rows[:12]:
        priority = _monitor_dict(row.get("priority"))
        terms = _monitor_evidence_terms(row.get("id"), row.get("title"), row.get("domain"), row.get("severity"), priority.get("rationale"))
        hard_terms = _monitor_case_hard_terms(row)
        policy_case = _monitor_policy_case_for(row, policy_cases, terms)
        related_receipts = []
        for receipt in receipts:
            relation = _monitor_receipt_relation(row, receipt, terms, hard_terms)
            if relation["include"]:
                related_receipts.append({"relation": relation, "receipt": receipt})
        related_receipts.sort(key=lambda item: (item["relation"]["score"], _safe_float(item["receipt"].get("evalScore"), 0)), reverse=True)
        direct_receipts = [item for item in related_receipts if item["relation"]["type"] == "explicit_case_id"]
        inferred_receipts = [item for item in related_receipts if item["relation"]["type"] != "explicit_case_id"]
        inferred_receipt_limit = max(0, 5 - len(direct_receipts)) if direct_receipts else 3
        visible_receipts = [*direct_receipts, *inferred_receipts[:inferred_receipt_limit]]
        related_reviews = []
        for review in review_rows:
            relation = _monitor_review_relation(row, review, terms, hard_terms)
            if relation["include"]:
                related_reviews.append({"relation": relation, "review": review})
        related_reviews.sort(key=lambda item: item["relation"]["score"], reverse=True)
        direct_reviews = [item for item in related_reviews if item["relation"]["type"] == "explicit_case_id"]
        inferred_reviews = [item for item in related_reviews if item["relation"]["type"] != "explicit_case_id"]
        inferred_review_limit = max(0, 5 - len(direct_reviews)) if direct_reviews else 3
        visible_reviews = [*direct_reviews, *inferred_reviews[:inferred_review_limit]]
        policy_ref_ids = _monitor_unique(
            [
                *_monitor_list(policy_case.get("policy_refs")),
                *[ref for receipt in visible_receipts for ref in _monitor_list(receipt["receipt"].get("policyRefs") or receipt["receipt"].get("policy_refs"))],
            ],
            limit=16,
        )
        policy_ref_rows = []
        for ref in policy_refs:
            ref_id = str(ref.get("policy_ref") or "")
            if ref_id not in set(policy_ref_ids):
                continue
            detail = cached_policy_detail(ref_id)
            first_match = _monitor_dict(_monitor_list(detail.get("matches"))[0] if _monitor_list(detail.get("matches")) else {})
            policy_ref_rows.append(
                {
                    **ref,
                    "policy_ref": ref_id,
                    "title": first_match.get("title") or ref.get("title") or ref_id,
                    "summary": first_match.get("allowed_action") or first_match.get("condition") or ref.get("summary"),
                    "detail": detail,
                }
            )
        trace_records = []
        for item in visible_receipts[:10]:
            receipt_policy_refs = _monitor_unique(
                _monitor_list(item["receipt"].get("policyRefs") or item["receipt"].get("policy_refs")),
                limit=8,
            )
            trace_policy_refs = _monitor_unique([*receipt_policy_refs, *policy_ref_ids], limit=12)
            trace_policy_rows = [
                {
                    "policy_ref": ref_row.get("policy_ref"),
                    "title": ref_row.get("title"),
                    "summary": ref_row.get("summary"),
                    "condition": _monitor_dict(_monitor_list(_monitor_dict(ref_row.get("detail")).get("matches"))[0] if _monitor_list(_monitor_dict(ref_row.get("detail")).get("matches")) else {}).get("condition"),
                    "allowed_action": _monitor_dict(_monitor_list(_monitor_dict(ref_row.get("detail")).get("matches"))[0] if _monitor_list(_monitor_dict(ref_row.get("detail")).get("matches")) else {}).get("allowed_action"),
                    "blocked_action": _monitor_dict(_monitor_list(_monitor_dict(ref_row.get("detail")).get("matches"))[0] if _monitor_list(_monitor_dict(ref_row.get("detail")).get("matches")) else {}).get("blocked_action"),
                }
                for ref_row in policy_ref_rows
                if str(ref_row.get("policy_ref") or "") in set(trace_policy_refs)
            ]
            trace_records.append(
                {
                    "receipt_id": item["receipt"].get("id"),
                    "case_id": row.get("id"),
                    "policy_case_id": policy_case.get("id"),
                    "policy_refs": trace_policy_refs,
                    "receipt_policy_refs": receipt_policy_refs,
                    "case_policy_refs": policy_ref_ids,
                    "policy_ref_rows": trace_policy_rows[:6],
                    "policy_link_source": "receipt.policyRefs + case doctrine" if receipt_policy_refs else "case doctrine",
                    "trace_id": item["receipt"].get("traceId"),
                    "trace_url": _monitor_trace_url(item["receipt"].get("traceId")),
                    "signature": item["receipt"].get("signature"),
                    "relation_type": item["relation"]["type"],
                    "relation_confidence": item["relation"]["confidence"],
                    "hard_match": item["relation"]["hard_match"],
                    "relation_score": item["relation"]["score"],
                    "case_link_source": item["receipt"].get("caseLinkSource"),
                    "case_link_confidence": item["receipt"].get("caseLinkConfidence"),
                    "eval_score": item["receipt"].get("evalScore"),
                    "gate": item["receipt"].get("gate"),
                    "tool_count": len(_monitor_list(item["receipt"].get("toolCalls"))),
                    "summary": item["receipt"].get("summary"),
                }
            )
        review_sessions = [
            {
                "review_session_id": item["review"].get("id"),
                "case_id": item["review"].get("case_id") or item["review"].get("caseId"),
                "status": item["review"].get("status") or _monitor_dict(item["review"].get("disposition")).get("decision"),
                "priority": item["review"].get("priority"),
                "owner": item["review"].get("owner"),
                "reason": item["review"].get("reason"),
                "relation_type": item["relation"]["type"],
                "relation_confidence": item["relation"]["confidence"],
                "hard_match": item["relation"]["hard_match"],
                "relation_score": item["relation"]["score"],
            }
            for item in visible_reviews[:10]
        ]
        receiver_actions = _monitor_unique(
            [action for item in visible_receipts for action in _monitor_list(item["receipt"].get("receiverActions"))],
            limit=10,
        )
        outcome_rows = [_monitor_dict(item["receipt"].get("outcomeEvidence")) for item in visible_receipts if _monitor_dict(item["receipt"].get("outcomeEvidence"))]
        graph_cases.append(
            {
                "case_id": row.get("id"),
                "caseId": row.get("id"),
                "policy_case_id": policy_case.get("id"),
                "policy_refs": policy_ref_ids,
                "policy_ref_rows": policy_ref_rows[:12],
                "receipt_ids": _monitor_unique([item["receipt"].get("id") for item in visible_receipts], limit=12),
                "trace_ids": _monitor_unique([item.get("trace_id") or item.get("signature") for item in trace_records], limit=12),
                "review_session_ids": _monitor_unique([item.get("review_session_id") for item in review_sessions], limit=12),
                "trace_records": trace_records,
                "review_sessions": review_sessions,
                "eval_dimensions": _monitor_eval_dimensions(row, [item["receipt"] for item in visible_receipts], [item["review"] for item in visible_reviews], policy_case),
                "outcome_evidence": {
                    "status": "measured_receipt" if outcome_rows else "dispatch_contract_only" if receiver_actions else "missing_outcome",
                    "dispatch_count": sum(int(_safe_float(item["receipt"].get("dispatchCount"), 0)) for item in visible_receipts),
                    "receiver_actions": receiver_actions,
                    "latest": outcome_rows[0] if outcome_rows else {},
                },
                "relationship_contract": {
                    "case_id": row.get("id"),
                    "trace_id_source": "receipt.traceId or receipt.signature",
                    "review_session_id_source": "review_training_ledger.id",
                    "policy_ref_source": "operational_doctrine_index.policy_refs",
                    "explicit_receipt_links": len(direct_receipts),
                    "explicit_review_links": len(direct_reviews),
                    "inferred_receipt_links": len([item for item in visible_receipts if item["relation"]["type"] != "explicit_case_id"]),
                    "inferred_review_links": len([item for item in visible_reviews if item["relation"]["type"] != "explicit_case_id"]),
                    "candidate_receipt_links": len(related_receipts),
                    "candidate_review_links": len(related_reviews),
                    "semantic_threshold": "include explicit links, distinctive case-token matches, or 3+ shared evidence terms",
                },
            }
        )
    trace_record_count = sum(len(row["trace_records"]) for row in graph_cases)
    distinct_trace_ids = _monitor_unique(
        [trace_id for row in graph_cases for trace_id in _monitor_list(row.get("trace_ids"))],
        limit=500,
    )
    distinct_review_session_ids = _monitor_unique(
        [session_id for row in graph_cases for session_id in _monitor_list(row.get("review_session_ids"))],
        limit=500,
    )
    return {
        "status": "ready",
        "mode": "monitor_evidence_graph",
        "case_count": len(graph_cases),
        "summary": {
            "receipt_count": len(receipts),
            "trace_record_count": trace_record_count,
            "distinct_trace_id_count": len(distinct_trace_ids),
            "review_session_count": len(review_rows),
            "linked_review_session_count": len(distinct_review_session_ids),
            "policy_ref_count": len(policy_refs),
            "cases_with_trace_records": sum(1 for row in graph_cases if row["trace_records"]),
            "cases_with_review_sessions": sum(1 for row in graph_cases if row["review_sessions"]),
            "cases_with_policy_refs": sum(1 for row in graph_cases if row["policy_refs"]),
        },
        "cases": graph_cases,
        "source_status": {"case_index": index.get("status"), "agent_ops_ledger": ledger.get("status"), "review_ledger": reviews.get("status"), "policy_doctrine": policy.get("status", "ready" if policy else "unavailable")},
        "source_watermark": _monitor_source_watermark(),
    }


def _monitor_evidence_cache_ttl_seconds() -> float:
    return max(5.0, _float_env("PARKPULSE_MONITOR_EVIDENCE_CACHE_TTL_SECONDS", 120.0))


def _monitor_evidence_cache_key(limit: int) -> str:
    return f"monitor-evidence-limit-{max(1, min(limit, 80))}"


def _monitor_evidence_storage_mode() -> str:
    requested = (os.getenv("PARKPULSE_MONITOR_EVIDENCE_STORAGE") or "local").strip().lower().replace("-", "_")
    if requested in {"mongo", "mongodb"}:
        return "mongodb"
    if requested in {"redis", "upstash"}:
        return "redis"
    return "local"


def _monitor_evidence_strip_secret(value: str | None) -> str:
    raw = str(value or "").strip()
    if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
        return raw[1:-1].strip()
    return raw


def _monitor_evidence_mongo_uri() -> str:
    return _monitor_evidence_strip_secret(
        os.getenv("MONGODB_DIRECT_URI")
        or os.getenv("MONGODB_URI")
        or os.getenv("MONGO_URI")
        or os.getenv("PARKPULSE_MONGODB_URI")
    )


def _monitor_evidence_mongo_database_name() -> str:
    configured = os.getenv("PARKPULSE_MONITOR_EVIDENCE_MONGO_DATABASE") or os.getenv("MONGODB_DATABASE")
    if configured and configured.strip():
        return configured.strip()
    uri = _monitor_evidence_mongo_uri()
    if uri:
        path = urlsplit(uri).path.strip("/")
        if path:
            return path.split("/")[0]
    return "parkpulse"


def _monitor_evidence_mongo_collection_name() -> str:
    return (os.getenv("PARKPULSE_MONITOR_EVIDENCE_MONGO_COLLECTION") or "monitor_evidence_snapshots").strip() or "monitor_evidence_snapshots"


def _monitor_evidence_mongo_client_ref() -> Any | None:
    global _monitor_evidence_mongo_client
    if _monitor_evidence_mongo_client is not None:
        return _monitor_evidence_mongo_client
    uri = _monitor_evidence_mongo_uri()
    if not uri:
        return None
    with _monitor_evidence_mongo_lock:
        if _monitor_evidence_mongo_client is not None:
            return _monitor_evidence_mongo_client
        try:
            from mongo_memory import _ensure_mongo_driver, _normalized_mongodb_uri
            import mongo_memory

            if not _ensure_mongo_driver() or mongo_memory.MongoClient is None:
                return None
            timeout_ms = max(250, _int_env("PARKPULSE_MONITOR_EVIDENCE_MONGO_TIMEOUT_MS", _int_env("MONGODB_OPERATION_TIMEOUT_MS", 1500)))
            _monitor_evidence_mongo_client = mongo_memory.MongoClient(
                _normalized_mongodb_uri(uri),
                serverSelectionTimeoutMS=timeout_ms,
                connectTimeoutMS=timeout_ms,
                socketTimeoutMS=timeout_ms,
                retryWrites=True,
            )
            return _monitor_evidence_mongo_client
        except Exception:
            return None


def _monitor_evidence_snapshot_path(limit: int) -> Path:
    configured = os.getenv("PARKPULSE_MONITOR_EVIDENCE_SNAPSHOT_PATH")
    if configured:
        path = Path(configured)
    else:
        path = Path("output") / f"{_monitor_evidence_cache_key(limit)}.json"
    return path if path.is_absolute() else Path.cwd() / path


def _monitor_evidence_snapshot_store(limit: int) -> dict[str, Any]:
    requested = _monitor_evidence_storage_mode()
    local_path = _monitor_evidence_snapshot_path(limit)
    if requested == "redis":
        redis_url = os.getenv("PARKPULSE_MONITOR_EVIDENCE_REDIS_URL") or os.getenv("REDIS_URL") or os.getenv("UPSTASH_REDIS_REST_URL")
        return {
            "backend": "redis",
            "mode": "redis_snapshot_cache",
            "shared_across_instances": True,
            "status": "redis_configured" if redis_url else "redis_unconfigured",
            "local_fallback_path": str(local_path),
        }
    if requested == "mongodb":
        mongo_uri = _monitor_evidence_mongo_uri()
        return {
            "backend": "mongodb",
            "mode": "mongodb_snapshot_cache",
            "shared_across_instances": True,
            "status": "mongodb_configured" if mongo_uri else "mongodb_unconfigured",
            "database": _monitor_evidence_mongo_database_name() if mongo_uri else None,
            "collection": os.getenv("PARKPULSE_MONITOR_EVIDENCE_MONGO_COLLECTION", "monitor_evidence_snapshots"),
            "local_fallback_path": str(local_path),
        }
    return {
        "backend": "local_json",
        "mode": "json_snapshot_cache",
        "shared_across_instances": False,
        "status": "ready" if local_path.exists() else "will_initialize_on_first_read",
        "path": str(local_path),
    }


def _monitor_evidence_copy(payload: dict[str, Any]) -> dict[str, Any]:
    return json.loads(json.dumps(payload, default=str))


def _monitor_evidence_summary(cases: list[dict[str, Any]], base_summary: dict[str, Any] | None = None) -> dict[str, Any]:
    summary = dict(base_summary or {})
    trace_record_count = sum(len(_monitor_list(row.get("trace_records"))) for row in cases)
    distinct_trace_ids = _monitor_unique(
        [trace_id for row in cases for trace_id in _monitor_list(row.get("trace_ids"))],
        limit=500,
    )
    distinct_review_session_ids = _monitor_unique(
        [session_id for row in cases for session_id in _monitor_list(row.get("review_session_ids"))],
        limit=500,
    )
    policy_ref_ids = _monitor_unique(
        [policy_ref for row in cases for policy_ref in _monitor_list(row.get("policy_refs"))],
        limit=500,
    )
    summary.update(
        {
            "trace_record_count": trace_record_count,
            "distinct_trace_id_count": len(distinct_trace_ids),
            "linked_review_session_count": len(distinct_review_session_ids),
            "linked_policy_ref_count": len(policy_ref_ids),
            "cases_with_trace_records": sum(1 for row in cases if _monitor_list(row.get("trace_records"))),
            "cases_with_review_sessions": sum(1 for row in cases if _monitor_list(row.get("review_sessions"))),
            "cases_with_policy_refs": sum(1 for row in cases if _monitor_list(row.get("policy_refs"))),
        }
    )
    return summary


def _monitor_evidence_filter_case(payload: dict[str, Any], case_id: str | None) -> dict[str, Any]:
    graph = _monitor_evidence_copy(payload)
    if not case_id:
        return graph
    cases = [row for row in _monitor_list(graph.get("cases")) if isinstance(row, dict) and str(row.get("case_id") or row.get("caseId") or "") == case_id]
    graph["cases"] = cases
    graph["case_count"] = len(cases)
    graph["summary"] = _monitor_evidence_summary(cases, _monitor_dict(graph.get("summary")))
    return graph


def _monitor_evidence_limit_from_key(key: str) -> int:
    suffix = str(key).rsplit("-", 1)[-1]
    return int(suffix) if suffix.isdigit() else 30


def _monitor_evidence_with_cache_metadata(payload: dict[str, Any], *, key: str, expires_at: float, created_at: float, state: str) -> dict[str, Any]:
    graph = _monitor_evidence_copy(payload)
    now = time.monotonic()
    current_watermark = _monitor_source_watermark()
    graph_watermark = _monitor_dict(graph.get("source_watermark"))
    limit = _monitor_evidence_limit_from_key(key)
    graph["evidence_cache"] = {
        "key": key,
        "state": state,
        "age_seconds": round(max(0.0, now - created_at), 3),
        "fresh_for_seconds": round(max(0.0, expires_at - now), 3),
        "refreshing": key in _monitor_evidence_refreshing,
        "mode": "backend_snapshot_stale_while_revalidate",
        "snapshot_path": str(_monitor_evidence_snapshot_path(limit)),
        "snapshot_store": _monitor_evidence_snapshot_store(limit),
        "source_fingerprint": graph_watermark.get("fingerprint"),
        "current_source_fingerprint": current_watermark.get("fingerprint"),
        "source_current": graph_watermark.get("fingerprint") == current_watermark.get("fingerprint"),
    }
    return graph


def _monitor_evidence_snapshot_created_monotonic(payload: dict[str, Any], fallback_path: Path | None = None, *, prefer_epoch: bool = False) -> float:
    created_epoch = _safe_float(payload.get("created_epoch"), 0)
    if prefer_epoch and created_epoch > 0:
        return time.monotonic() - max(0.0, time.time() - created_epoch)
    created_at = _safe_float(payload.get("created_monotonic"), 0)
    if created_at > 0:
        return created_at
    if created_epoch > 0:
        return time.monotonic() - max(0.0, time.time() - created_epoch)
    if fallback_path is not None:
        try:
            created_epoch = fallback_path.stat().st_mtime
            return time.monotonic() - max(0.0, time.time() - created_epoch)
        except OSError:
            pass
    return time.monotonic()


def _monitor_evidence_snapshot_payload(limit: int, graph: dict[str, Any]) -> dict[str, Any]:
    bounded_limit = max(1, min(limit, 80))
    source_watermark = _monitor_dict(graph.get("source_watermark"))
    now_epoch = time.time()
    created_at_date = datetime.fromtimestamp(now_epoch, tz=timezone.utc)
    return {
        "status": "ready",
        "mode": "monitor_evidence_snapshot",
        "created_at": created_at_date.isoformat(),
        "created_at_date": created_at_date,
        "created_epoch": now_epoch,
        "created_monotonic": time.monotonic(),
        "ttl_seconds": _monitor_evidence_cache_ttl_seconds(),
        "key": _monitor_evidence_cache_key(bounded_limit),
        "limit": bounded_limit,
        "source_fingerprint": source_watermark.get("fingerprint"),
        "source_watermark": source_watermark,
        "graph": graph,
    }


def _monitor_evidence_mongo_indexes(collection: Any) -> list[str]:
    created: list[str] = []
    ttl_seconds = max(0, _int_env("PARKPULSE_MONITOR_EVIDENCE_MONGO_TTL_SECONDS", 0))
    index_specs: list[tuple[Any, dict[str, Any]]] = [
        ([("key", 1)], {"name": "monitor_evidence_key_idx", "background": True}),
        ([("source_fingerprint", 1)], {"name": "monitor_evidence_source_fingerprint_idx", "background": True}),
    ]
    if ttl_seconds > 0:
        index_specs.append(([("created_at_date", 1)], {"name": "monitor_evidence_created_ttl_idx", "expireAfterSeconds": ttl_seconds, "background": True}))
    for spec, options in index_specs:
        try:
            name = collection.create_index(spec, **options)
            created.append(str(name or options.get("name") or spec))
        except AttributeError:
            break
    return created


def monitor_evidence_storage_status(*, force_refresh: bool = False) -> dict[str, Any]:
    global _monitor_evidence_storage_status_cache
    ttl = max(0.0, _float_env("PARKPULSE_MONITOR_EVIDENCE_STORAGE_STATUS_TTL_SECONDS", 30.0))
    now = time.monotonic()
    if not force_refresh and ttl > 0 and _monitor_evidence_storage_status_cache and _monitor_evidence_storage_status_cache[0] > now:
        return _monitor_evidence_copy(_monitor_evidence_storage_status_cache[1])

    mode = _monitor_evidence_storage_mode()
    store = _monitor_evidence_snapshot_store(40)
    local_path = _monitor_evidence_snapshot_path(40)
    base = {
        "status": "ready",
        "ready": True,
        "mode": store.get("mode"),
        "backend": store.get("backend"),
        "requested_storage": mode,
        "shared_across_instances": bool(store.get("shared_across_instances")),
        "snapshot_store": store,
        "local_fallback_path": str(local_path),
        "readiness_issues": [],
    }
    if mode == "local":
        payload = {**base, "writable": os.access(local_path.parent if local_path.parent.exists() else local_path.parent.parent, os.W_OK) if local_path.parent.parent.exists() else None}
    elif mode == "redis":
        payload = {
            **base,
            "status": "degraded",
            "ready": False,
            "shared_across_instances": False,
            "readiness_issues": ["Redis Monitor evidence snapshots are registered as a future cache target; this runtime currently serves MongoDB or local JSON snapshots."],
            "fallback": "local_json_snapshot",
        }
    else:
        uri = _monitor_evidence_mongo_uri()
        if not uri:
            payload = {
                **base,
                "status": "degraded",
                "ready": False,
                "configured": False,
                "connected": False,
                "readiness_issues": ["PARKPULSE_MONITOR_EVIDENCE_STORAGE=mongodb but no Mongo URI is configured."],
            }
        elif not _truthy_env("PARKPULSE_MONITOR_EVIDENCE_READINESS_PING", True):
            payload = {
                **base,
                "status": "configured",
                "ready": True,
                "configured": True,
                "connected": None,
                "database": _monitor_evidence_mongo_database_name(),
                "collection": _monitor_evidence_mongo_collection_name(),
                "validation_path": "Set PARKPULSE_MONITOR_EVIDENCE_READINESS_PING=true to validate Mongo read/write and index creation on readiness.",
            }
        else:
            started = time.monotonic()
            client = _monitor_evidence_mongo_client_ref()
            if client is None:
                payload = {
                    **base,
                    "status": "degraded",
                    "ready": False,
                    "configured": True,
                    "connected": False,
                    "database": _monitor_evidence_mongo_database_name(),
                    "collection": _monitor_evidence_mongo_collection_name(),
                    "readiness_issues": ["Mongo Monitor evidence snapshot client is unavailable."],
                }
            else:
                database = _monitor_evidence_mongo_database_name()
                collection_name = _monitor_evidence_mongo_collection_name()
                try:
                    collection = client[database][collection_name]
                    index_names = _monitor_evidence_mongo_indexes(collection) if _truthy_env("PARKPULSE_MONITOR_EVIDENCE_MONGO_CREATE_INDEXES", True) else []
                    max_time_ms = max(250, _int_env("PARKPULSE_MONITOR_EVIDENCE_MONGO_QUERY_TIMEOUT_MS", 1000))
                    write_checked = _truthy_env("PARKPULSE_MONITOR_EVIDENCE_READINESS_WRITE_CHECK", True)
                    if write_checked:
                        collection.replace_one(
                            {"_id": "__monitor_evidence_readiness__"},
                            {
                                "_id": "__monitor_evidence_readiness__",
                                "status": "ready",
                                "mode": "monitor_evidence_storage_readiness",
                                "updated_at": datetime.now(timezone.utc),
                                "storage_key": "monitor_evidence_snapshot",
                            },
                            upsert=True,
                        )
                    collection.find_one({"_id": "__monitor_evidence_readiness__"}, {"_id": 1}, max_time_ms=max_time_ms)
                    payload = {
                        **base,
                        "status": "ready",
                        "ready": True,
                        "configured": True,
                        "connected": True,
                        "database": database,
                        "collection": collection_name,
                        "write_checked": write_checked,
                        "indexes": index_names,
                        "latency_ms": int((time.monotonic() - started) * 1000),
                    }
                except Exception as error:
                    payload = {
                        **base,
                        "status": "degraded",
                        "ready": False,
                        "configured": True,
                        "connected": False,
                        "database": database,
                        "collection": collection_name,
                        "readiness_issues": [str(error)[:240]],
                        "latency_ms": int((time.monotonic() - started) * 1000),
                    }

    if ttl > 0:
        _monitor_evidence_storage_status_cache = (now + ttl, _monitor_evidence_copy(payload))
    return _monitor_evidence_copy(payload)


def _read_monitor_evidence_mongo_snapshot(limit: int, current_watermark: dict[str, Any] | None = None) -> tuple[float, float, dict[str, Any]] | None:
    if _monitor_evidence_storage_mode() != "mongodb" or not _monitor_evidence_mongo_uri():
        return None
    client = _monitor_evidence_mongo_client_ref()
    if client is None:
        return None
    key = _monitor_evidence_cache_key(limit)
    try:
        max_time_ms = max(250, _int_env("PARKPULSE_MONITOR_EVIDENCE_MONGO_QUERY_TIMEOUT_MS", 1000))
        collection = client[_monitor_evidence_mongo_database_name()][_monitor_evidence_mongo_collection_name()]
        payload = collection.find_one({"_id": key}, {"_id": 0}, max_time_ms=max_time_ms)
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    graph = _monitor_dict(payload.get("graph"))
    if not graph:
        return None
    if current_watermark and _monitor_dict(graph.get("source_watermark")).get("fingerprint") != current_watermark.get("fingerprint"):
        return None
    created_at = _monitor_evidence_snapshot_created_monotonic(payload, prefer_epoch=True)
    ttl = _safe_float(payload.get("ttl_seconds"), _monitor_evidence_cache_ttl_seconds())
    return created_at + max(5.0, ttl), created_at, graph


def _write_monitor_evidence_mongo_snapshot(limit: int, graph: dict[str, Any]) -> bool:
    if _monitor_evidence_storage_mode() != "mongodb" or not _monitor_evidence_mongo_uri():
        return False
    client = _monitor_evidence_mongo_client_ref()
    if client is None:
        return False
    key = _monitor_evidence_cache_key(limit)
    try:
        payload = _monitor_evidence_snapshot_payload(limit, graph)
        payload["_id"] = key
        payload["storage_backend"] = "mongodb"
        collection = client[_monitor_evidence_mongo_database_name()][_monitor_evidence_mongo_collection_name()]
        collection.replace_one({"_id": key}, payload, upsert=True)
        return True
    except Exception:
        return False


def _read_monitor_evidence_snapshot(limit: int, current_watermark: dict[str, Any] | None = None) -> tuple[float, float, dict[str, Any]] | None:
    mongo_snapshot = _read_monitor_evidence_mongo_snapshot(limit, current_watermark)
    if mongo_snapshot:
        return mongo_snapshot
    path = _monitor_evidence_snapshot_path(limit)
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return None
    graph = _monitor_dict(payload.get("graph"))
    if not graph:
        return None
    if current_watermark and _monitor_dict(graph.get("source_watermark")).get("fingerprint") != current_watermark.get("fingerprint"):
        return None
    created_at = _monitor_evidence_snapshot_created_monotonic(payload, fallback_path=path)
    ttl = _monitor_evidence_cache_ttl_seconds()
    expires_at = created_at + ttl
    return expires_at, created_at, graph


def _write_monitor_evidence_snapshot(limit: int, graph: dict[str, Any]) -> None:
    _write_monitor_evidence_mongo_snapshot(limit, graph)
    path = _monitor_evidence_snapshot_path(limit)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = _monitor_evidence_snapshot_payload(limit, graph)
    payload["storage_backend"] = "local_json"
    path.write_text(json.dumps(payload, indent=2, sort_keys=True, default=str), encoding="utf-8")


def _store_monitor_evidence_cache(key: str, limit: int, graph: dict[str, Any]) -> tuple[float, float, dict[str, Any]]:
    created_at = time.monotonic()
    expires_at = created_at + _monitor_evidence_cache_ttl_seconds()
    clean_graph = _monitor_evidence_copy(graph)
    with _monitor_evidence_lock:
        _monitor_evidence_cache[key] = (expires_at, created_at, clean_graph)
    with contextlib.suppress(Exception):
        _write_monitor_evidence_snapshot(limit, clean_graph)
    return expires_at, created_at, clean_graph


def _refresh_monitor_evidence_cache(limit: int, key: str) -> None:
    try:
        graph = asyncio.run(_monitor_evidence_graph(case_id=None, limit=limit))
        _store_monitor_evidence_cache(key, limit, graph)
    except Exception as error:
        print(f"ParkPulse monitor evidence refresh failed for {key}: {error}")
    finally:
        with _monitor_evidence_lock:
            _monitor_evidence_refreshing.discard(key)


def _trigger_monitor_evidence_refresh(limit: int, key: str) -> None:
    with _monitor_evidence_lock:
        if key in _monitor_evidence_refreshing:
            return
        _monitor_evidence_refreshing.add(key)
    _monitor_evidence_executor.submit(_refresh_monitor_evidence_cache, limit, key)


async def _monitor_evidence_graph_cached(case_id: str | None = None, *, limit: int = 30, force_refresh: bool = False) -> dict[str, Any]:
    bounded_limit = max(1, min(limit, 80))
    key = _monitor_evidence_cache_key(bounded_limit)
    now = time.monotonic()
    current_watermark = _monitor_source_watermark()
    if not force_refresh:
        with _monitor_evidence_lock:
            cached = _monitor_evidence_cache.get(key)
        if cached:
            expires_at, created_at, graph = cached
            graph_watermark = _monitor_dict(graph.get("source_watermark"))
            if graph_watermark.get("fingerprint") != current_watermark.get("fingerprint"):
                with _monitor_evidence_lock:
                    _monitor_evidence_cache.pop(key, None)
            else:
                state = "fresh" if expires_at > now else "stale"
                if expires_at <= now:
                    _trigger_monitor_evidence_refresh(bounded_limit, key)
                return _monitor_evidence_with_cache_metadata(
                    _monitor_evidence_filter_case(graph, case_id),
                    key=key,
                    expires_at=expires_at,
                    created_at=created_at,
                    state=state,
                )

        snapshot = _read_monitor_evidence_snapshot(bounded_limit, current_watermark)
        if snapshot:
            expires_at, created_at, graph = snapshot
            with _monitor_evidence_lock:
                _monitor_evidence_cache[key] = (expires_at, created_at, graph)
            state = "snapshot_fresh" if expires_at > now else "snapshot_stale"
            if expires_at <= now:
                _trigger_monitor_evidence_refresh(bounded_limit, key)
            return _monitor_evidence_with_cache_metadata(
                _monitor_evidence_filter_case(graph, case_id),
                key=key,
                expires_at=expires_at,
                created_at=created_at,
                state=state,
            )

    graph = await _monitor_evidence_graph(case_id=None, limit=bounded_limit)
    expires_at, created_at, stored_graph = _store_monitor_evidence_cache(key, bounded_limit, graph)
    return _monitor_evidence_with_cache_metadata(
        _monitor_evidence_filter_case(stored_graph, case_id),
        key=key,
        expires_at=expires_at,
        created_at=created_at,
        state="rebuilt" if force_refresh else "cold_rebuilt",
    )


async def _advance_fast_park_from_wall_clock() -> int:
    global _last_fast_park_step_at
    now = time.monotonic()
    if _last_fast_park_step_at <= 0:
        _last_fast_park_step_at = now
        return 0
    steps = min(5, int((now - _last_fast_park_step_at) // _fast_park_step_interval_seconds))
    if steps <= 0:
        return 0
    for _ in range(steps):
        await _fast_park_simulation.step()
    _last_fast_park_step_at += steps * _fast_park_step_interval_seconds
    if _truthy_env("PARKPULSE_HEARTBEAT_CONTROLLER_SYNC_ON_READ", False):
        await _maybe_run_heartbeat_controller(steps)
    return steps


def _latest_live_agents_smoke_report() -> dict[str, Any]:
    report_path = Path(os.getenv("PARKPULSE_LIVE_AGENTS_SMOKE_REPORT", "output/qa/live-all-agents-smoke.json"))
    if not report_path.is_absolute():
        report_path = Path.cwd() / report_path
    if not report_path.exists():
        return {
            "status": "missing",
            "mode": "live_all_agents_smoke",
            "report_path": str(report_path),
            "summary": {
                "status": "missing",
                "activated_role_count": 0,
                "activated_department_count": 0,
                "role_failures": [],
                "scenario_failures": [],
            },
            "readiness_issues": ["Run `make live-agents-smoke` to generate the latest all-agent proof report."],
        }
    try:
        payload = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as error:
        return {
            "status": "error",
            "mode": "live_all_agents_smoke",
            "report_path": str(report_path),
            "summary": {"status": "error"},
            "readiness_issues": [str(error)[:240]],
        }
    if isinstance(payload, dict):
        return {**payload, "report_path": str(report_path)}
    return {
        "status": "error",
        "mode": "live_all_agents_smoke",
        "report_path": str(report_path),
        "summary": {"status": "error"},
        "readiness_issues": ["Live all-agents smoke report is not a JSON object."],
    }


async def _fast_agent_monitoring() -> dict[str, Any]:
    state = await _cached_hot_endpoint("park_state_lite", _hot_endpoint_ttls()["park_state"], _fast_park_state_lite)
    scenario = state.get("guestFlow", {}).get("activeScenario", {}) if isinstance(state.get("guestFlow"), dict) else {}
    alerts = state.get("alerts", []) if isinstance(state.get("alerts"), list) else []
    rides = state.get("rides", []) if isinstance(state.get("rides"), list) else []
    queues = state.get("queues", []) if isinstance(state.get("queues"), list) else []
    blocked_count = sum(1 for alert in alerts if str(alert.get("severity", "")).lower() in {"critical", "blocked"})
    review_count = sum(1 for alert in alerts if str(alert.get("severity", "")).lower() in {"high", "warning", "review"})
    overall_status = "blocked" if blocked_count else "review" if review_count else "clear"
    return {
        "monitoring_id": f"PP-MON-FAST-{int(time.time() * 1000)}",
        "created_at": _now_iso(),
        "domain": "amusement_park_operations",
        "entrypoint": "lazy-main",
        "mode": "stale_while_revalidate_fast_monitoring",
        "overall_status": overall_status,
        "scenario": {
            "key": scenario.get("key", "ride_down") if isinstance(scenario, dict) else "ride_down",
            "name": scenario.get("name") or scenario.get("title") or "ParkPulse scenario" if isinstance(scenario, dict) else "ParkPulse scenario",
        },
        "summary": {
            "action_count": 0,
            "clear_count": 0 if overall_status != "clear" else 1,
            "review_count": review_count,
            "blocked_count": blocked_count,
            "open_signal_count": len(alerts),
            "ride_count": len(rides),
            "queue_count": len(queues),
            "full_runtime_loaded": _parkpulse_app is not None,
            "cache_policy": "hot_path_summary",
        },
        "policy_lanes": [
            {"id": "ride_safety", "status": "watch" if review_count or blocked_count else "clear"},
            {"id": "guest_flow", "status": "watch" if alerts else "clear"},
            {"id": "staffing", "status": "clear"},
        ],
        "supervised_actions": [],
        "runtime_governance": {
            "status": "summarized",
            "source": "lazy-main",
            "full_runtime": _full_runtime_status(),
        },
        "operator_checklist": [
            "Escalate to React Agent for confirmed incidents.",
            "Escalate to Proact Agent when weak signals trend upward.",
            "Require human review for safety-sensitive actions.",
        ],
    }


async def _deep_agent_monitoring() -> dict[str, Any]:
    load_timeout = _float_env("PARKPULSE_DEEP_MONITORING_LOAD_TIMEOUT_SECONDS", 20.0)
    run_timeout = _float_env("PARKPULSE_DEEP_MONITORING_TIMEOUT_SECONDS", 8.0)
    module = await _get_full_module(timeout=load_timeout)
    payload = await asyncio.wait_for(
        asyncio.to_thread(lambda: asyncio.run(module.build_park_agent_monitoring_response())),
        timeout=run_timeout,
    )
    if isinstance(payload, dict):
        payload.setdefault("entrypoint", "full-runtime")
        payload.setdefault("mode", "deep_monitoring")
    return payload


async def _fast_park_action(target: str, action: str) -> dict[str, Any]:
    from park_action_result import build_park_action_result
    from park_simulation import park_simulation

    result = await park_simulation.execute_action(target, action)
    return {
        **build_park_action_result(result, target, action),
        "governance": {
            "allowed": result.get("status") != "unknown_action",
            "gate_status": "clear" if result.get("status") != "unknown_action" else "blocked",
            "policy_contract": {
                "status": "fast_path",
                "target": target,
                "action": action,
                "issues": [] if result.get("status") != "unknown_action" else ["Unsupported action."],
            },
            "findings": ["Fast local action path used to keep the demo run loop responsive."],
        },
    }


def _fast_integration_status() -> dict[str, Any]:
    try:
        from arize_config import get_arize_status
        from evaluator_loop import evaluator_loop_status
        from gcp_trace_eval import get_gcp_trace_eval_status

        gcp_trace_eval = get_gcp_trace_eval_status().public_dict()
        arize = get_arize_status().public_dict()
        evaluator_loop = evaluator_loop_status()
    except Exception as error:
        gcp_trace_eval = {"platform": "GCP internal trace/eval", "ready": False, "mode": "status_error", "readiness_issues": [str(error)[:240]]}
        arize = {"ready": False, "enabled": False}
        evaluator_loop = {"status": "status_error", "readiness_issues": [str(error)[:240]]}
    return {
        "domain": "amusement_park_operations",
        "agent": {"name": "ParkPulse AI", "role": "parkpulse_decision_bridge"},
        "entrypoint": "lazy-main",
        "ready": True,
        "full_app_loaded": _parkpulse_app is not None,
        "full_runtime": _full_runtime_status(),
        "load_error": _load_error,
        "gemini": {"ready": False, "provider": "lazy runtime warming"},
        "gcp_trace_eval": gcp_trace_eval,
        "evaluator_loop": evaluator_loop,
        "online_improvement": {"provider": "gcp", "ready": True},
        "arize": arize,
        "mongo": {"mode": "lazy_unavailable_until_full_runtime", "connected": False},
        "bigquery": {"enabled": True, "ready": False},
        "status": "fast_recovery",
    }


def _lightweight_integration_status() -> dict[str, Any]:
    gemini_ready = bool(os.getenv("GOOGLE_API_KEY") or os.getenv("GOOGLE_CLOUD_PROJECT"))
    bigquery_enabled = str(os.getenv("ENABLE_BIGQUERY_ANALYTICS", "")).lower() in {"1", "true", "yes", "on"}
    mongo_status = _hot_mongo_status()
    return {
        "domain": "amusement_park_operations",
        "agent": {"name": "ParkPulse AI", "role": "parkpulse_decision_bridge"},
        "entrypoint": "lazy-main",
        "ready": True,
        "full_app_loaded": _parkpulse_app is not None,
        "full_runtime": _full_runtime_status(),
        "load_error": _load_error,
        "gemini": {
            "ready": gemini_ready,
            "provider": "vertex_or_api_env" if gemini_ready else "not_configured",
        },
        "gcp_trace_eval": {"ready": bool(os.getenv("GOOGLE_CLOUD_PROJECT")), "mode": "hot_path_env_check", "platform": "GCP internal trace/eval"},
        "evaluator_loop": {"status": "not_loaded_on_readiness_path"},
        "online_improvement": {"provider": "gcp", "ready": True},
        "arize": {"ready": False, "enabled": False, "mode": "not_loaded_on_readiness_path"},
        "mongo": mongo_status,
        "bigquery": {"enabled": bigquery_enabled, "ready": bigquery_enabled and bool(os.getenv("GOOGLE_CLOUD_PROJECT"))},
        "status": "lightweight_readiness",
    }


def _dependency_ready(value: dict[str, Any], ready_key: str = "ready") -> bool:
    if not isinstance(value, dict):
        return False
    if ready_key in value:
        return bool(value.get(ready_key))
    if "connected" in value:
        return bool(value.get("connected"))
    return str(value.get("status", "")).lower() in {"ok", "ready", "healthy", "integrated"}


def _hot_delivery_outbox_health() -> dict[str, Any]:
    path = os.getenv("PARKPULSE_DELIVERY_OUTBOX", "/tmp/parkpulse/delivery_outbox.jsonl")
    directory = os.path.dirname(path) or "."
    try:
        os.makedirs(directory, exist_ok=True)
        durable_count = None
        if os.getenv("PARKPULSE_READINESS_COUNT_DELIVERY_OUTBOX", "").strip().lower() in {"1", "true", "yes", "on"} and os.path.exists(path):
            with open(path, "rb") as file:
                durable_count = sum(1 for _ in file)
        return {
            "mode": "hot_path_durable_jsonl_outbox",
            "ready": True,
            "path": path,
            "directory": directory,
            "durable_count": durable_count,
            "counted": durable_count is not None,
            "processing": "append-first, idempotency-keyed dispatch records; full outbox inspection is off the readiness hot path.",
        }
    except Exception as error:
        return {
            "mode": "hot_path_durable_jsonl_outbox",
            "ready": False,
            "path": path,
            "directory": directory,
            "error": str(error)[:240],
        }


def _hot_platform_store_health() -> dict[str, Any]:
    path = os.getenv("PARKPULSE_PLATFORM_DB", "/tmp/parkpulse/park_data.db")
    if not _truthy(os.getenv("PARKPULSE_READINESS_DEEP_PLATFORM_STORE"), False):
        return {
            "ready": True,
            "mode": "hot_path_platform_store_contract",
            "source_of_truth": "local_sqlite_wal",
            "path": path,
            "schema_version": 1,
            "registered_store_count": None,
            "observed_store_count": None,
            "authority_boundary": "SQLite owns local transactional app authority. Deep registry inspection is off the readiness hot path.",
            "readiness_issues": [],
        }
    try:
        from platform_store import platform_store_status

        status = platform_store_status()
        return {
            "ready": bool(status.get("ready")),
            "mode": status.get("mode"),
            "source_of_truth": status.get("source_of_truth"),
            "path": status.get("path"),
            "schema_version": status.get("schema_version"),
            "registered_store_count": status.get("registered_store_count"),
            "observed_store_count": status.get("observed_store_count"),
            "authority_boundary": status.get("authority_boundary"),
            "readiness_issues": status.get("readiness_issues", []),
        }
    except Exception as error:
        return {
            "ready": False,
            "mode": "sqlite_platform_registry",
            "source_of_truth": "local_sqlite_wal",
            "path": os.getenv("PARKPULSE_PLATFORM_DB", "/tmp/parkpulse/park_data.db"),
            "readiness_issues": [str(error)[:240]],
        }


def _readiness_payload() -> dict[str, Any]:
    integration = _lightweight_integration_status()
    delivery = _hot_delivery_outbox_health()
    platform = _hot_platform_store_health()
    monitor_storage = monitor_evidence_storage_status()

    dependency_status = {
        "platform_store": platform,
        "monitor_evidence_snapshot": monitor_storage,
        "gemini": integration.get("gemini", {}),
        "mongo": integration.get("mongo", {}),
        "bigquery": integration.get("bigquery", {}),
        "delivery_outbox": delivery,
        "gcp_trace_eval": integration.get("gcp_trace_eval", {}),
        "evaluator_loop": integration.get("evaluator_loop", {}),
    }
    hard_dependencies = ["platform_store", "gemini", "bigquery"]
    soft_dependencies = ["mongo", "delivery_outbox", "monitor_evidence_snapshot"]
    hard_blockers = [name for name in hard_dependencies if not _dependency_ready(dependency_status.get(name, {}))]
    degraded = [name for name in soft_dependencies if not _dependency_ready(dependency_status.get(name, {}))]
    status = "not_ready" if hard_blockers else "degraded" if degraded else "ok"
    return {
        "service": "parkpulse-api",
        "status": status,
        "entrypoint": "lazy-main",
        "build_id": LAZY_ROUTER_BUILD_ID,
        "uptime_ms": int((time.time() - _started_at) * 1000),
        "full_app_loaded": _parkpulse_app is not None,
        "full_runtime": _full_runtime_status(),
        "load_error": _load_error,
        "dependency_status": dependency_status,
        "readiness_issues": [f"{name} is not ready" for name in hard_blockers],
        "degraded_dependencies": [f"{name} is degraded or unavailable" for name in degraded],
    }


async def _readiness_payload_bounded() -> dict[str, Any]:
    timeout = max(0.5, _float_env("PARKPULSE_READYZ_TIMEOUT_SECONDS", 2.5))
    try:
        return await asyncio.wait_for(asyncio.to_thread(_readiness_payload), timeout=timeout)
    except Exception as error:
        issue = _issue_text(error, f"Readiness payload timed out after {timeout:g}s.")
        return {
            "service": "parkpulse-api",
            "status": "degraded",
            "mode": "readyz_timeout_fallback",
            "entrypoint": "lazy-main",
            "build_id": LAZY_ROUTER_BUILD_ID,
            "uptime_ms": int((time.time() - _started_at) * 1000),
            "full_app_loaded": _parkpulse_app is not None,
            "full_runtime": _full_runtime_status(),
            "load_error": _load_error,
            "readiness_issues": [issue],
            "degraded_dependencies": ["readiness builder exceeded hot-path budget"],
            "dependency_status": {
                "mongo": _hot_mongo_status(),
                "full_runtime": _full_runtime_status(),
            },
            "timeout_seconds": timeout,
        }


