def _copilot_request_message(request_payload: dict[str, Any]) -> tuple[str, list[dict[str, Any]]]:
    messages = [
        item
        for item in request_payload.get("messages", [])
        if isinstance(item, dict) and str(item.get("content") or "").strip()
    ][-8:]
    message = str(request_payload.get("message") or "").strip()
    if not message and messages:
        message = str(messages[-1].get("content") or "").strip()
    return message or "What is the biggest park risk right now?", messages


def _lightweight_copilot_state_summary(state: dict[str, Any]) -> dict[str, Any]:
    flow = state.get("guestFlow", {}) if isinstance(state.get("guestFlow"), dict) else {}
    rides = [item for item in flow.get("rides", []) if isinstance(item, dict)] if isinstance(flow.get("rides"), list) else []
    zones = [item for item in flow.get("zones", []) if isinstance(item, dict)] if isinstance(flow.get("zones"), list) else []
    paths = [item for item in flow.get("paths", []) if isinstance(item, dict)] if isinstance(flow.get("paths"), list) else []
    weather = state.get("weather", {}) if isinstance(state.get("weather"), dict) else {}
    food = state.get("foodInventory", {}) if isinstance(state.get("foodInventory"), dict) else {}
    sorted_rides = sorted(rides, key=lambda item: _safe_float(item.get("waitMins"), 0), reverse=True)
    sorted_zones = sorted(zones, key=lambda item: _safe_float(item.get("density"), 0), reverse=True)
    sorted_paths = sorted(paths, key=lambda item: _safe_float(item.get("congestionLevel"), 0), reverse=True)
    return {
        "status": "ready",
        "mode": "lightweight_copilot_state",
        "top_rides": [
            {
                "id": ride.get("id"),
                "name": ride.get("name") or ride.get("id"),
                "wait_mins": ride.get("waitMins"),
                "queue_guests": ride.get("queueGuests"),
                "status": ride.get("status"),
                "staff": (
                    f"{ride.get('staffAvailable')}/{ride.get('staffRequired')}"
                    if ride.get("staffAvailable") is not None and ride.get("staffRequired") is not None
                    else None
                ),
            }
            for ride in sorted_rides[:5]
        ],
        "crowded_zones": [
            {
                "id": zone.get("id"),
                "name": zone.get("name") or zone.get("id"),
                "density": zone.get("density"),
                "wait_mins": zone.get("waitMins"),
                "intent": zone.get("dominantIntent"),
            }
            for zone in sorted_zones[:5]
        ],
        "constrained_paths": [
            {
                "from": path.get("fromName") or path.get("from"),
                "to": path.get("toName") or path.get("to"),
                "walk_mins": path.get("walkMinutes"),
                "congestion": path.get("congestionLevel"),
                "status": path.get("status"),
            }
            for path in sorted_paths[:5]
        ],
        "weather": {
            "condition": weather.get("condition"),
            "heat_index_f": weather.get("heatIndexF"),
            "storm_risk": weather.get("stormRisk"),
        },
        "food": {
            "mode": food.get("mode"),
            "risk": food.get("risk"),
            "low_stock_items": food.get("lowStockItems") if isinstance(food.get("lowStockItems"), list) else [],
        },
        "operations_audit": state.get("operationsAudit") if isinstance(state.get("operationsAudit"), dict) else {},
    }


def _lightweight_copilot_recommendation(message: str, route: dict[str, Any], state_summary: dict[str, Any]) -> dict[str, Any]:
    role = str(route.get("selected_role") or "scan")
    top_ride = (state_summary.get("top_rides") or [{}])[0]
    top_zone = (state_summary.get("crowded_zones") or [{}])[0]
    top_path = (state_summary.get("constrained_paths") or [{}])[0]
    reported_coaster = "the reported coaster queue" if "coaster" in message.lower() else "the reported queue"
    reported_parade = "the parade pinch point" if "parade" in message.lower() else "the busiest reported area"
    ride_name = top_ride.get("name") or reported_coaster
    zone_name = top_zone.get("name") or reported_parade
    path_label = (
        f"{top_path.get('from')} to {top_path.get('to')}"
        if top_path.get("from") or top_path.get("to")
        else "the most constrained path"
    )
    lower = message.lower()
    if "weather" in lower or "storm" in lower or "heat" in lower:
        label = "Keep the turn read-only and prepare weather/comfort monitoring."
        action = "Monitor weather risk, keep indoor/calm alternates visible, and ask for operator approval before shelter or closure actions."
    elif "food" in lower or "mobile order" in lower:
        label = "Protect food capacity before sending new demand."
        action = "Hold broad food promotions, point guests to alternate capacity, and task staff to verify pickup backlog before dispatch."
    elif "staff" in lower:
        label = "Check staff coverage before moving anyone."
        action = "Use role-compatible redeployment only after confirming break windows, certification, and active post coverage."
    elif "queue" in lower or "coaster" in lower or "ride" in lower:
        label = f"Relieve pressure around {ride_name} without creating a second crowd."
        action = f"Split flow away from {ride_name}, keep messaging calm near {zone_name}, and station staff near {path_label} before any guest push."
    else:
        label = f"Use {role.title()} Agent as a bounded advisor."
        action = f"Read live state, keep the turn non-dispatching, and escalate only after the operator confirms the affected location and approval."
    return {
        "role": role,
        "label": label,
        "action": action,
        "gate": "propose_only",
        "dispatch_count": 0,
        "execute": False,
        "policy_gates": route.get("policy_gates", []),
        "primary_evidence": {
            "top_ride": top_ride,
            "top_zone": top_zone,
            "top_path": top_path,
        },
    }


def _lightweight_copilot_options(recommendation: dict[str, Any], route: dict[str, Any]) -> list[dict[str, Any]]:
    return [
        {
            "label": recommendation.get("label") or "Bounded operating proposal",
            "verdict": "selected",
            "reason": "Uses the fast state snapshot and department role route without importing the full runtime.",
            "projected_effect": "Operator gets a concrete proposal with no state mutation or receiver dispatch.",
        },
        {
            "label": "Wait for full copilot runtime",
            "verdict": "rejected",
            "reason": "Full runtime is not loaded on this request path and previously caused long Cloud Run waits.",
            "projected_effect": "Could improve receipt depth, but would risk the conversation panel hanging.",
        },
        {
            "label": "Dispatch immediately",
            "verdict": "blocked",
            "reason": "The lightweight copilot path is propose-only unless the full policy-gated runtime is loaded.",
            "projected_effect": "No guest, worker, or equipment receiver is mutated from this path.",
        },
    ]


def _lightweight_copilot_semantic_enabled() -> bool:
    return _truthy_env("PARKPULSE_COPILOT_LIGHTWEIGHT_SEMANTIC_MEMORY", True) and (
        _truthy_env("PARKPULSE_COPILOT_SEMANTIC_MEMORY", False)
        or _truthy_env("PARKPULSE_MONGO_MODEL_EMBEDDINGS", False)
    )


def _lightweight_copilot_memory_doc_summary(document: dict[str, Any]) -> dict[str, Any]:
    return {
        key: document.get(key)
        for key in (
            "_id",
            "title",
            "summary",
            "incidentType",
            "scenarioKey",
            "lesson",
            "rule",
            "recommendedAction",
            "score",
        )
        if document.get(key) is not None
    }


def _lightweight_semantic_scenario_key(state: dict[str, Any], memory: dict[str, Any] | None = None) -> str:
    if isinstance(memory, dict) and memory.get("scenario_key"):
        return str(memory.get("scenario_key"))
    guest_flow = state.get("guestFlow") if isinstance(state.get("guestFlow"), dict) else {}
    active = guest_flow.get("activeScenario") if isinstance(guest_flow.get("activeScenario"), dict) else {}
    return str(active.get("key") or "ride_down")


def _schedule_lightweight_role_cache_warmup(message: str, state: dict[str, Any], selected_role: str, scenario_key: str) -> dict[str, Any]:
    interval = max(1.0, _float_env("PARKPULSE_COPILOT_LIGHTWEIGHT_ROLE_CACHE_WARMUP_INTERVAL_SECONDS", 30.0))
    role = str(selected_role or "scan")
    key = f"{scenario_key}:{role}"
    now = time.monotonic()
    with _semantic_role_cache_warmup_lock:
        last = _semantic_role_cache_warmups.get(key, 0.0)
        if now - last < interval:
            return {"status": "throttled", "scenario_key": scenario_key, "role": role}
        _semantic_role_cache_warmups[key] = now

    def operation() -> None:
        try:
            from mongo_memory import get_operational_intelligence

            get_operational_intelligence(message, scenario_key, role)
        except Exception:
            return

    _semantic_role_cache_executor.submit(operation)
    return {"status": "queued", "scenario_key": scenario_key, "role": role}


def _lightweight_scan_cache_miss_fallback(
    *,
    message: str,
    state: dict[str, Any],
    state_summary: dict[str, Any],
    memory: dict[str, Any],
    started: float,
    timeout: float,
) -> dict[str, Any]:
    scenario_key = _lightweight_semantic_scenario_key(state, memory)
    warmup = _schedule_lightweight_role_cache_warmup(message, state, "scan", scenario_key)
    top_ride = state_summary.get("top_ride") if isinstance(state_summary.get("top_ride"), dict) else {}
    top_zone = state_summary.get("top_zone") if isinstance(state_summary.get("top_zone"), dict) else {}
    top_path = state_summary.get("top_path") if isinstance(state_summary.get("top_path"), dict) else {}
    ride_name = top_ride.get("name") or top_ride.get("id") or "top ride"
    zone_name = top_zone.get("name") or top_zone.get("id") or "highest-density zone"
    return {
        "status": "ready",
        "source": "mongo_operational_memory_lightweight",
        "query": memory.get("query") or message,
        "scenario_key": scenario_key,
        "agent_role": "scan_agent",
        "cache_policy": memory.get("cache_policy") or "role_cache_only",
        "retrieval_method": "role_context_cache_static_fallback",
        "summary": "Scan role cache was cold; served deterministic weak-signal context and queued Mongo role-cache warmup.",
        "model_api": (memory.get("status") or {}).get("modelApi") if isinstance(memory.get("status"), dict) else {},
        "model_api_key_configured": bool(os.getenv("MONGODB_MODEL_API_KEY")),
        "readiness_issues": [],
        "fallback_reason": "role_context_cache_miss",
        "warmup": warmup,
        "elapsed_ms": round((time.monotonic() - started) * 1000, 2),
        "timeout_ms": round(timeout * 1000, 2),
        "cache_status": "static_fallback",
        "counts": {"playbooks": 1, "incidents": 1, "learnings": 1},
        "retrieved": {
            "playbooks": [
                {
                    "_id": f"scan_static_playbook_{scenario_key}",
                    "title": "Scan weak-signal triage",
                    "summary": f"Watch {ride_name}, {zone_name}, path congestion, weather, and guest-care notes before recommending action.",
                    "scenarioKey": scenario_key,
                    "recommendedAction": "Surface uncertainty, name the signal, and request operator confirmation before mutation.",
                }
            ],
            "incidents": [
                {
                    "_id": f"scan_static_incident_{scenario_key}",
                    "summary": f"Cold role-cache fallback for {scenario_key}; compare live ride, zone, and path pressure before escalation.",
                    "scenarioKey": scenario_key,
                }
            ],
            "learnings": [
                {
                    "_id": f"scan_static_learning_{scenario_key}",
                    "lesson": "Scan answers should observe and explain weak signals, not dispatch or mutate park operations.",
                    "scenarioKey": scenario_key,
                }
            ],
        },
        "state_focus": {
            "top_ride": top_ride,
            "top_zone": top_zone,
            "top_path": top_path,
        },
    }


def _compact_lightweight_copilot_semantic_memory(memory: dict[str, Any]) -> dict[str, Any]:
    status = memory.get("status") if isinstance(memory.get("status"), dict) else {}
    retrieved = memory.get("retrieved") if isinstance(memory.get("retrieved"), dict) else {}
    playbooks = retrieved.get("playbooks") if isinstance(retrieved.get("playbooks"), list) else []
    incidents = retrieved.get("incidents") if isinstance(retrieved.get("incidents"), list) else []
    learnings = retrieved.get("learnings") if isinstance(retrieved.get("learnings"), list) else []
    retrieval_method = str(retrieved.get("method") or "")
    model_api = status.get("modelApi") if isinstance(status.get("modelApi"), dict) else {}
    model_api_enabled = bool(model_api.get("enabled"))
    counts = {"playbooks": len(playbooks), "incidents": len(incidents), "learnings": len(learnings)}
    total_count = sum(counts.values())
    degraded_reasons: list[str] = []
    if not retrieval_method or retrieval_method in {"degraded_empty", "role_context_cache_miss"}:
        degraded_reasons.append("Semantic memory returned no usable hot-path context.")
    if model_api_enabled and not retrieval_method.startswith("mongodb_vector_search") and not retrieval_method.startswith("role_context_cache"):
        degraded_reasons.append(f"Model API is enabled but retrieval used {retrieval_method or 'unknown'} instead of vector search.")
    if total_count <= 0:
        degraded_reasons.append("No playbooks, incidents, or learnings were retrieved.")
    return {
        "status": "ready" if not degraded_reasons else "degraded",
        "source": "mongo_operational_memory_lightweight",
        "query": memory.get("query"),
        "scenario_key": memory.get("scenario_key"),
        "agent_role": memory.get("agent_role"),
        "cache_policy": memory.get("cache_policy"),
        "retrieval_method": retrieval_method,
        "summary": memory.get("summary"),
        "model_api": model_api,
        "model_api_key_configured": bool(os.getenv("MONGODB_MODEL_API_KEY")),
        "readiness_issues": degraded_reasons,
        "counts": counts,
        "retrieved": {
            "playbooks": [_lightweight_copilot_memory_doc_summary(row) for row in playbooks[:3] if isinstance(row, dict)],
            "incidents": [_lightweight_copilot_memory_doc_summary(row) for row in incidents[:3] if isinstance(row, dict)],
            "learnings": [_lightweight_copilot_memory_doc_summary(row) for row in learnings[:3] if isinstance(row, dict)],
        },
    }


def _lightweight_retrieve_operational_context(
    query: str,
    state: dict[str, Any],
    limit: int,
    agent_role: str | None,
    cache_policy: str,
) -> dict[str, Any]:
    from mongo_memory import retrieve_operational_context

    return retrieve_operational_context(query, state, limit, agent_role, cache_policy, False)


async def _lightweight_copilot_semantic_memory_context(
    message: str,
    state: dict[str, Any],
    state_summary: dict[str, Any],
    route: dict[str, Any],
) -> dict[str, Any]:
    if not _lightweight_copilot_semantic_enabled():
        return {"status": "not_requested", "reason": "Lightweight semantic memory is disabled."}
    started = time.monotonic()
    selected_role = str(route.get("selected_role") or "scan")
    cache_policy = os.getenv("PARKPULSE_COPILOT_LIGHTWEIGHT_SEMANTIC_MEMORY_CACHE_POLICY", "").strip()
    if not cache_policy:
        cache_policy = "fresh_retrieval" if _truthy_env("PARKPULSE_MONGO_MODEL_EMBEDDINGS", False) else os.getenv(
            "PARKPULSE_COPILOT_SEMANTIC_MEMORY_CACHE_POLICY",
            "role_cache_only",
        )
    if selected_role == "scan" and cache_policy == "fresh_retrieval":
        cache_policy = os.getenv("PARKPULSE_COPILOT_LIGHTWEIGHT_SCAN_SEMANTIC_MEMORY_CACHE_POLICY", "role_cache_only")
    cache_key = json.dumps(
        {
            "message": message,
            "role": selected_role,
            "cache_policy": cache_policy,
            "state": {
                "top_ride": state_summary.get("top_ride"),
                "top_zone": state_summary.get("top_zone"),
                "top_path": state_summary.get("top_path"),
                "weather": state_summary.get("weather"),
            },
            "model": os.getenv("MONGODB_MODEL_EMBEDDING_MODEL", "voyage-4-lite"),
            "path": os.getenv("MONGODB_MODEL_EMBEDDING_PATH", "modelEmbedding"),
        },
        sort_keys=True,
        default=str,
    )
    ttl = max(0.0, _float_env("PARKPULSE_COPILOT_LIGHTWEIGHT_SEMANTIC_MEMORY_CACHE_TTL_SECONDS", 45.0))
    now = time.monotonic()
    if ttl > 0:
        with _lightweight_semantic_memory_lock:
            cached = _lightweight_semantic_memory_cache.get(cache_key)
            if cached and cached[0] > now:
                payload = dict(cached[1])
                payload["cache_status"] = "hit"
                payload["elapsed_ms"] = round((time.monotonic() - started) * 1000, 2)
                return payload
    try:
        timeout = max(0.2, _float_env("PARKPULSE_COPILOT_LIGHTWEIGHT_SEMANTIC_MEMORY_TIMEOUT_SECONDS", _float_env("PARKPULSE_COPILOT_SEMANTIC_MEMORY_TIMEOUT_SECONDS", 2.0)))
        memory = await asyncio.wait_for(
            asyncio.to_thread(
                _lightweight_retrieve_operational_context,
                message,
                state if isinstance(state, dict) else {},
                3,
                selected_role,
                cache_policy,
            ),
            timeout=timeout,
        )
        payload = _compact_lightweight_copilot_semantic_memory(memory if isinstance(memory, dict) else {})
        if (
            selected_role == "scan"
            and payload.get("status") == "degraded"
            and payload.get("retrieval_method") == "role_context_cache_miss"
        ):
            payload = _lightweight_scan_cache_miss_fallback(
                message=message,
                state=state if isinstance(state, dict) else {},
                state_summary=state_summary if isinstance(state_summary, dict) else {},
                memory=memory if isinstance(memory, dict) else {},
                started=started,
                timeout=timeout,
            )
        payload["elapsed_ms"] = round((time.monotonic() - started) * 1000, 2)
        payload["timeout_ms"] = round(timeout * 1000, 2)
        payload.setdefault("cache_status", "miss")
        if ttl > 0:
            with _lightweight_semantic_memory_lock:
                if len(_lightweight_semantic_memory_cache) >= 128:
                    oldest_key = min(_lightweight_semantic_memory_cache, key=lambda key: _lightweight_semantic_memory_cache[key][0])
                    _lightweight_semantic_memory_cache.pop(oldest_key, None)
                _lightweight_semantic_memory_cache[cache_key] = (now + ttl, dict(payload))
        return payload
    except Exception as error:
        return {
            "status": "timeout" if isinstance(error, (asyncio.TimeoutError, TimeoutError)) else "error",
            "source": "mongo_operational_memory_lightweight",
            "model_api_key_configured": bool(os.getenv("MONGODB_MODEL_API_KEY")),
            "cache_policy": cache_policy,
            "readiness_issues": [_issue_text(error, "Lightweight semantic memory exceeded the hot-path timeout.")],
            "elapsed_ms": round((time.monotonic() - started) * 1000, 2),
        }


async def _lightweight_copilot_model_response(
    *,
    message: str,
    messages: list[dict[str, Any]],
    route: dict[str, Any],
    state_summary: dict[str, Any],
    recommendation: dict[str, Any],
    options: list[dict[str, Any]],
    semantic_memory_context: dict[str, Any],
) -> dict[str, Any]:
    prompt = {
        "task": (
            "Answer as ParkPulse's department copilot for an amusement-park operator. "
            "Be natural, concise, and grounded only in the supplied state, route, policy gates, and recommendation. "
            "Do not claim that a dispatch, closure, medical/security action, or equipment command happened."
        ),
        "operator_message": message,
        "recent_messages": [{"role": item.get("role"), "content": item.get("content")} for item in messages[-6:]],
        "selected_role": route.get("selected_role"),
        "route_reason": route.get("why"),
        "policy_gates": route.get("policy_gates", []),
        "state_summary": state_summary,
        "semantic_memory": {
            "status": semantic_memory_context.get("status"),
            "retrieval_method": semantic_memory_context.get("retrieval_method"),
            "summary": semantic_memory_context.get("summary"),
            "counts": semantic_memory_context.get("counts"),
            "retrieved": semantic_memory_context.get("retrieved"),
            "readiness_issues": semantic_memory_context.get("readiness_issues"),
        },
        "recommended_action": recommendation,
        "options_considered": options,
        "required_json": {
            "answer": "one natural operator-facing paragraph with the concrete recommendation",
            "reasoning_bullets": ["2-4 short bullets grounded in supplied facts"],
            "operator_next": "the next concrete operator step",
            "confidence": 0.0,
        },
    }
    try:
        from gemini_hard_timeout import generate_gemini_json_hard_timeout

        started = time.monotonic()
        result = await generate_gemini_json_hard_timeout(
            prompt,
            timeout_seconds=max(0.5, _float_env("PARKPULSE_COPILOT_LIGHTWEIGHT_MODEL_TIMEOUT_SECONDS", 4.0)),
            max_output_tokens=max(160, _int_env("PARKPULSE_COPILOT_LIGHTWEIGHT_MODEL_MAX_TOKENS", 520)),
            temperature=_float_env("PARKPULSE_COPILOT_LIGHTWEIGHT_MODEL_TEMPERATURE", 0.25),
        )
        parsed = _parse_gemini_json_text(str(result.get("text") or "{}"))
        return {
            "source": "gemini_lightweight_copilot",
            "model": os.getenv("PARKPULSE_FAST_GEMINI_MODEL") or os.getenv("GEMINI_MODEL") or os.getenv("GOOGLE_GENAI_MODEL"),
            "transport": result.get("transport"),
            "provider_ready": True,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "answer": str(parsed.get("answer") or "").strip(),
            "reasoning_bullets": [str(item) for item in parsed.get("reasoning_bullets", []) if item][:4]
            if isinstance(parsed.get("reasoning_bullets"), list)
            else [],
            "operator_next": str(parsed.get("operator_next") or "").strip(),
            "confidence": parsed.get("confidence", 0.74),
            "semantic_memory": semantic_memory_context,
        }
    except Exception as error:
        evidence = recommendation.get("primary_evidence", {}) if isinstance(recommendation.get("primary_evidence"), dict) else {}
        top_ride = evidence.get("top_ride", {}) if isinstance(evidence.get("top_ride"), dict) else {}
        top_zone = evidence.get("top_zone", {}) if isinstance(evidence.get("top_zone"), dict) else {}
        answer = (
            f"{recommendation.get('label')} My proposal is: {recommendation.get('action')} "
            f"I am keeping this propose-only because the full copilot runtime is not loaded and no receiver dispatch should happen from this fast path."
        )
        return {
            "source": "deterministic_lightweight_copilot",
            "model": None,
            "provider_ready": False,
            "provider_error": str(error)[:300],
            "answer": answer,
            "reasoning_bullets": [
                f"Selected role: {route.get('selected_role') or 'scan'} because {route.get('why') or 'the role router matched the operator text'}.",
                f"Highest ride pressure: {top_ride.get('name') or 'unknown'} at {top_ride.get('wait_mins', '--')} minutes.",
                f"Busiest zone: {top_zone.get('name') or 'unknown'} at density {top_zone.get('density', '--')}.",
                "No guest, worker, equipment, or memory mutation was dispatched.",
            ],
            "operator_next": "Approve a full policy-gated action or ask a narrower follow-up.",
            "confidence": 0.68,
            "semantic_memory": semantic_memory_context,
        }


async def _build_lightweight_copilot_payload(request_payload: dict[str, Any]) -> dict[str, Any]:
    started = time.monotonic()
    stages: list[dict[str, Any]] = []

    def mark(stage: str) -> None:
        stages.append({"stage": stage, "total_ms": round((time.monotonic() - started) * 1000, 2)})

    message, messages = _copilot_request_message(request_payload)
    mode = str(request_payload.get("mode") or "auto")
    requested_turn_mode = str(request_payload.get("turn_mode") or request_payload.get("turnMode") or "auto").lower()
    state_timeout = max(0.25, _float_env("PARKPULSE_COPILOT_LIGHTWEIGHT_STATE_TIMEOUT_SECONDS", 1.5))
    cached_state = _hot_endpoint_cache.get("park_state_lite")
    if cached_state and cached_state[0] > time.monotonic():
        state = cached_state[1]
        mark("state_cache")
    elif _truthy_env("PARKPULSE_COPILOT_LIGHTWEIGHT_STATE_CACHE_ONLY", True):
        state = {
            "status": "degraded",
            "mode": "lightweight_state_cache_miss",
            "operationsAudit": {
                "ready": False,
                "readiness_issues": ["Fast state cache was cold; live state refresh is deferred off the copilot hot path."],
            },
            "guestFlow": {"rides": [], "zones": [], "paths": []},
        }
        mark("state_cache_miss")
    else:
        try:
            state = await asyncio.wait_for(
                _cached_hot_endpoint("park_state_lite", _hot_endpoint_ttls()["park_state"], _fast_park_state_lite),
                timeout=state_timeout,
            )
            mark("state")
        except Exception as error:
            state = {
                "status": "degraded",
                "operationsAudit": {"ready": False, "readiness_issues": [str(error)[:240]]},
                "guestFlow": {"rides": [], "zones": [], "paths": []},
            }
            mark("state_fallback")
    if isinstance(state, dict):
        _schedule_fast_state_mongo_sync(state, reason="lightweight_copilot_state")
    route = route_agent_role(message, mode)
    mark("route")
    state_summary = _lightweight_copilot_state_summary(state if isinstance(state, dict) else {})
    recommendation = _lightweight_copilot_recommendation(message, route, state_summary)
    options = _lightweight_copilot_options(recommendation, route)
    mark("recommendation")
    semantic_memory_context = await _lightweight_copilot_semantic_memory_context(
        message,
        state if isinstance(state, dict) else {},
        state_summary,
        route,
    )
    mark("semantic_memory")
    conversation_response = await _lightweight_copilot_model_response(
        message=message,
        messages=messages,
        route=route,
        state_summary=state_summary,
        recommendation=recommendation,
        options=options,
        semantic_memory_context=semantic_memory_context,
    )
    mark("conversation_response")
    answer = conversation_response.get("answer") or str(recommendation.get("action") or "")
    reasoning_summary = [
        *([str(item) for item in conversation_response.get("reasoning_bullets", [])] if isinstance(conversation_response.get("reasoning_bullets"), list) else []),
        f"Conversation source: {conversation_response.get('source')}.",
    ]
    response_mode = (
        "answer"
        if requested_turn_mode == "answer" or not any(term in message.lower() for term in ("do", "fix", "reroute", "send", "move", "open", "close", "queue", "stuck"))
        else "propose"
    )
    semantic_memory_context = conversation_response.get("semantic_memory") if isinstance(conversation_response.get("semantic_memory"), dict) else semantic_memory_context
    semantic_memory_tool = (
        {
            "id": "semantic_memory",
            "tool": "memory.retrieve_semantic_context",
            "label": "Retrieve semantic memory",
            "status": semantic_memory_context.get("status"),
            "output": semantic_memory_context.get("retrieval_method") or semantic_memory_context.get("source"),
        }
        if isinstance(semantic_memory_context, dict) and semantic_memory_context.get("status") != "not_requested"
        else None
    )
    return {
        "status": "complete",
        "mode": response_mode,
        "message": message,
        "answer": answer,
        "reasoning_summary": reasoning_summary,
        "options_considered": options,
        "clarifying_question": None,
        "recommended_action": recommendation,
        "map_grounding": {
            "status": "lightweight",
            "primary_zone": recommendation.get("primary_evidence", {}).get("top_zone") if isinstance(recommendation.get("primary_evidence"), dict) else {},
            "primary_path": recommendation.get("primary_evidence", {}).get("top_path") if isinstance(recommendation.get("primary_evidence"), dict) else {},
        },
        "impact_replay": None,
        "reasoning_evaluation": {
            "status": "lightweight",
            "overall": 78,
            "verdict": "usable_with_conditions",
            "conditions": ["Full impact replay is deferred until the full runtime is warm."],
        },
        "agent_runtime": {
            "status": "lightweight_complete",
            "mode": "main_asgi_lightweight_copilot",
            "full_runtime_loaded": _parkpulse_app is not None,
            "summary": {"completed_stages": len(stages), "total_stages": len(stages)},
        },
        "conversation_response": conversation_response,
        "semantic_memory_context": semantic_memory_context,
        "tool_trace": {
            "tool_calls": [
                {"tool": "get_park_state_lite", "status": state_summary.get("status"), "capability": "read", "output": "lightweight state summary"},
                {"tool": "route_agent_role", "status": "complete", "capability": "reason", "output": route.get("selected_role")},
                *([{"tool": "memory.retrieve_semantic_context", "status": semantic_memory_context.get("status"), "capability": "read", "output": semantic_memory_context.get("retrieval_method")}] if semantic_memory_tool else []),
                {"tool": "copilot.respond", "status": "complete", "capability": "reason", "output": conversation_response.get("source")},
            ],
            "summary": {"policy_gate": "propose_only", "state_mutation": False},
        },
        "tool_call_timeline": [
            {"id": "state", "tool": "get_park_state_lite", "label": "Read fast park state", "status": state_summary.get("status")},
            {"id": "route", "tool": "route_agent_role", "label": "Select department agent", "status": "complete", "output": route.get("selected_role")},
            *([semantic_memory_tool] if semantic_memory_tool else []),
            {"id": "answer", "tool": "copilot.respond", "label": "Answer operator", "status": "complete", "output": conversation_response.get("source")},
        ],
        "turn_contract": {
            "mode": response_mode,
            "will_act": False,
            "dispatch_count": 0,
            "state_mutation": False,
            "reason": "Lightweight copilot is propose-only until the full policy-gated runtime is warm.",
        },
        "route": route,
        "selected_role": route.get("selected_role"),
        "live_state_summary": state_summary,
        "action_receipt": None,
        "run_telemetry": None,
        "conversation_memory": {
            "turn_count": len(messages) + 1,
            "raw_message": message,
            "effective_message": message,
            "conversation_intent": response_mode,
            "chat_brain_source": "main_asgi_lightweight_copilot",
            "constraints": route.get("policy_gates", []),
            "semantic_memory_status": semantic_memory_context.get("status") if isinstance(semantic_memory_context, dict) else None,
        },
        "latency_diagnostics": {
            "mode": "main_asgi_lightweight_copilot",
            "status": "complete",
            "total_ms": round((time.monotonic() - started) * 1000, 2),
            "stages": stages,
            "full_runtime": _full_runtime_status(),
        },
    }


